public class SkillState : State<Player>
{
	public static string staticID = string.Empty;

	public string skillID = "UnnamedSkill";

	public StatData skillData;

	public ElementType element;

	public bool isUnlocked;

	public bool hasSignatureVariant;

	public bool signatureUnlocked;

	public bool isSignature;

	public int currentLevel;

	public bool isUltimate;

	public BoolVarStat empoweredStat;

	public bool isBasic;

	public bool isDash;

	public bool isMovementSkill;

	public bool isJumpSkill;

	public bool isMeleeSkill;

	public bool isProjectileSkill;

	public bool isBuffSkill;

	public bool isSummonSkill;

	public static int MaxSkillFlags = 8;

	public float currentAnimTime;

	public float animStartTime;

	public float animHoldTime;

	public float animExecTime;

	public float cancelThreshold = 1f;

	public float runThreshold = 1f;

	public float exitThreshold = 1f;

	public Vector2 inputVector;

	public int skillSlot = -1;

	public bool isChargeSkill;

	public bool applyStopElementStatus;

	public bool disableStartCooldown;

	public bool startCooldownOnEnter = true;

	public Cooldown cooldownRef;

	public bool useSmartCD;

	public bool cdStarted;

	public bool allowSelfTransition;

	public bool allowRepeating;

	public bool repeatLock;

	public bool isHoldSkill;

	public bool holdStarted;

	public bool holdReleased;

	public bool updateHoldAnim = true;

	public bool skillExecuted;

	public SkillState prevSkillState;

	private SkillState cancelToDashSkill;

	public virtual bool IsEmpowered => empoweredStat.CurrentValue;

	public virtual string OnEnterAnimStr => parent.NextHandAnimStr;

	public virtual string OnHoldAnimStr => parent.LastHandAnimStr;

public class EarthDashState : BaseDashState
{
	public new static string staticID = "EarthDash";

	private EarthWave currentEW;

	public EarthDashState(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		InitChargeSkillSettings(1, 0f, skillData, this);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			ApplyStopElement();
			currentEW = ChaosInst<EarthWave>(EarthWave.Prefab, parent.transform.position);
			currentEW.transform.localScale *= 1.25f;
			currentEW.SetSkillData(parent.skillCategory, skillID);
			currentEW.moveVector = inputVector;
			currentEW.maxWaveCount = 12;
			currentEW.wavePoolSize = 12;
			currentEW.waveStartDelay = 0f;
			currentEW.spawnRate = 0.025f;
			currentEW.destroyDelay = 0.0625f;
			currentEW.spawnAtOrigin = true;
			currentEW.homing = false;
			currentEW.singleHitOnly = false;
			currentEW.loseDamageOnCollisions = false;
			currentEW.stopWaveOnHit = false;
			currentEW.disableCastingCircle = true;
			currentEW.playSoundOnce = true;
			SoundManager.PlayAudioWithDistance("RockExplode", parent.transform.position, null, 24f, -1f, 1.1f);
		}
	}

	public override void OnExit()
	{
		if (cooldownReady)
		{
			if (currentEW != null && !IsEmpowered)
			{
				currentEW.StopWave();
			}
			currentEW = null;
		}
		base.OnExit();
	}
}

public class EarthSpikeBasic : MeleeAttackState
{
	public new static string staticID = "EarthSpikeBasic";

	private EarthSpike curEarthSpike;

	private SortSpriteLayer spriteSorter;

	private FacingDirection curFacingDir;

	private static float normFinalCancel = 0.75f;

	private static float normFinalRun = 1.05f;

	private static float normFinalExit = 1.15f;

	public EarthSpikeBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		attackPrefab = EarthSpike.Prefab;
		setParent = false;
		destroyAttackObjectOnExit = false;
		maxComboCount = 2;
		animStartTime = 0.15f;
		animExecTime = 0.25f;
		baseCancelThreshold = 0.7f;
		finalCancelThreshold = normFinalCancel;
		baseRunThreshold = 0.85f;
		finalRunThreshold = normFinalRun;
		baseExitThreshold = 1f;
		finalExitThreshold = normFinalExit;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 32f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = attackMoveSpeedMod;
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		if (IsEmpowered)
		{
			maxComboCount = ((!repeatFinalHit) ? 1 : 2);
			finalCancelThreshold = 0.7f;
			finalRunThreshold = 0.9f;
			finalExitThreshold = 1f;
		}
		else
		{
			maxComboCount = ((!repeatFinalHit) ? 2 : 3);
			finalCancelThreshold = normFinalCancel;
			finalRunThreshold = normFinalRun;
			finalExitThreshold = normFinalExit;
		}
	}

	public override void OnEnter()
	{
		base.OnEnter();
		flipObjectForBackhand = true;
		base.ExecuteAttack();
		curEarthSpike = (EarthSpike)currentAttackObject;
		if (IsEmpowered)
		{
			curEarthSpike.isEmpowered = true;
		}
		spriteSorter = curEarthSpike.transform.GetComponentInChildren<SortSpriteLayer>();
		curFacingDir = Globals.GetPrimaryDirection(inputVector);
		if (parent.forehandAnimPlayed)
		{
			curEarthSpike.followScript.followTransform = parent.rightHandTransform;
			spriteSorter.yValueOffset = ((curFacingDir != FacingDirection.Up) ? (-1.5f) : 0f);
		}
		else
		{
			curEarthSpike.followScript.followTransform = parent.leftHandTransform;
		}
	}

	public override void ExecuteAttack()
	{
		curEarthSpike.anim.Play("Idle", -1, 0f);
		if (IsEmpowered)
		{
			curEarthSpike.anim.Play("IdleLarge", -1, 0f);
			curEarthSpike.attack.atkInfo.damage = Mathf.FloorToInt((float)curEarthSpike.attack.atkInfo.damage * 1.75f);
			curEarthSpike.attack.atkInfo.hitStunDurationModifier = 1.5f;
			curEarthSpike.attack.atkInfo.knockbackMultiplier = 20f;
		}
		curEarthSpike.followScript.enabled = false;
		curEarthSpike.transform.position = parent.attackOriginTrans.position + (Vector3)(inputVector * 0.3f);
		if (curFacingDir == FacingDirection.Right || curFacingDir == FacingDirection.Left)
		{
			flipObjectForBackhand = false;
			curEarthSpike.anim.PlayDirectional("Attack" + ((!parent.forehandAnimPlayed) ? "RightLH" : "RightRH") + ((!IsEmpowered) ? string.Empty : "Large"));
			if (curFacingDir == FacingDirection.Right)
			{
				Vector3 localScale = curEarthSpike.transform.localScale;
				localScale.x *= -1f;
				curEarthSpike.transform.localScale = localScale;
			}
			if (IsEmpowered)
			{
				CameraController.ShakeCamera(0.3f);
				PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(RockDebrisType.Default, 4, parent.attackOriginTrans.position + (Vector3)inputVector * 2f, RockDebrisEmitter.MedCircleExplosionOverride);
			}
			else
			{
				CameraController.ShakeCamera(0.17f);
				RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
				RockDebrisType debrisType = RockDebrisType.Default;
				int? particleCount = 5;
				Vector3? position = parent.attackOriginTrans.position;
				Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
				poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			}
		}
		if (curFacingDir != FacingDirection.Up)
		{
			spriteSorter.yValueOffset = -1.5f;
		}
		parent.movement.EndMovement();
	}

	public override void OnExit()
	{
		base.OnExit();
		if (curEarthSpike != null)
		{
			curEarthSpike.EndAttack();
		}
		parent.movement.EndMovement();
	}
}

	public virtual string OnHoldAnimStr => parent.LastHandAnimStr;

	public SkillState(string newName, FSM newFSM, Player newEnt)
		: base(newName, newFSM, newEnt)
	{
		InitializeSkill();
		skillID = newName;
		SetSkillData();
		RegisterSkill();
	}

	public void InitializeSkill()
	{
		currentLevel = 0;
		isUltimate = false;
		isUnlocked = false;
		signatureUnlocked = false;
		empoweredStat = new BoolVarStat(newBaseVal: false);
	}

	public void SetSkillData()
	{
		skillData = StatManager.GetSkillData(parent.skillCategory, skillID);
		if (skillData == null)
		{
			Debug.Log("No skillData found in StatManager for skillID: " + skillID + " in category: " + parent.skillCategory);
			return;
		}
		element = (ElementType)Enum.Parse(typeof(ElementType), skillData.GetValue<string>("elementType"));
		if (!elementSkillDict[element].Contains(skillID))
		{
			elementSkillDict[element].Add(skillID);
		}
	}

	public void RegisterSkill()
	{
		parent.skillsDict[skillID] = this;
		parent.cooldownManager.Add(skillID, skillData.GetValue<float>("cooldown", currentLevel), skillData, this);
		cooldownRef = parent.cooldownManager.cooldowns[skillID];
	}

	public virtual void SetAnimTimes(float newStart = 0f, float newHold = 0.2f, float newExecute = 0.3f, float newCancel = 0.6f, float newRun = 0.8f, float newExit = 1f)
	{
		animStartTime = newStart;
		animHoldTime = newHold;
		animExecTime = newExecute;
		cancelThreshold = newCancel;
		runThreshold = newRun;
		exitThreshold = newExit;
	}

	public void InitChargeSkillSettings(int maxCharges, float delayBetweenCharges, StatData statData, SkillState skillState)
	{
		isChargeSkill = true;
		cooldownRef.isChargeSkill = true;
		cooldownRef.chargeCount = maxCharges;
		cooldownRef.MaxChargeCount = maxCharges;
		cooldownRef.chargeDelayTime = delayBetweenCharges;
		cooldownRef.statData = statData;
		cooldownRef.skillState = skillState;
		cooldownRef.remainingTimeStopwatchID = -1;
		cooldownRef.delayStopwatchID = -1;
	}

	public virtual void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		empoweredStat.Modify(givenMod, givenStatus);
		if (parent.skillEmpowerEventHandlers != null)
		{
			parent.skillEmpowerEventHandlers(this);
		}
	}

	public virtual bool IsReady()
	{
		if ((isMovementSkill && !parent.MovementEnabled) || (isUltimate && !IsOverdriveReady()) || (!isUltimate && !cooldownRef.Ready))
		{
			return false;
		}
		if (allowSelfTransition && !allowRepeating && repeatLock)
		{
			return false;
		}
		return true;
	}

	public virtual bool IsOverdriveReady()
	{
		return true;
	}

	public bool Transition()
	{
		if (!IsReady() || (!allowSelfTransition && fsm.currentStateName == skillID))
		{
			return false;
		}
		fsm.ChangeState(skillID, allowSelfTransition: true);
		return true;
	}

	public int SetSkillSlot()
	{
		for (int i = 0; i < parent.assignedSkills.Length; i++)
		{
			if (parent.assignedSkills[i] != null && parent.assignedSkills[i].skillID == skillID)
			{
				skillSlot = i;
				return skillSlot;
			}
		}
		skillSlot = -1;
		return skillSlot;
	}

	public void SetRepeatLock(bool setLock = true)
	{
		repeatLock = setLock;
	}

	public void UpdateRepeatLock(string buttonName = "")
	{
		if (skillSlot != -1)
		{
			if (buttonName == string.Empty)
			{
				buttonName = "Skill" + skillSlot;
			}
			if (parent.inputDevice.GetButtonUp(buttonName))
			{
				SetRepeatLock(setLock: false);
			}
		}
	}

	public virtual void StartCooldownTimer(float overrideValue = -1f, bool expendCharge = true)
	{
		if (useSmartCD)
		{
			if (cdStarted)
			{
				return;
			}
			cdStarted = true;
		}
		if ((skillData.GetValue<float>("cooldown") == 0f && overrideValue == -1f) || parent == null || parent.gameObject == null || !parent.gameObject.activeSelf)
		{
			return;
		}
		if (isChargeSkill)
		{
			if (expendCharge && cooldownRef.chargeCount > 0)
			{
				cooldownRef.chargeCount = Mathf.Max(0, cooldownRef.chargeCount - ((!(overrideValue > 0f)) ? 1 : ((int)overrideValue)));
			}
			parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
		}
		else
		{
			parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
		}
	}

	public void ApplyStopElement()
	{
		if (parent.dotManager != null)
		{
			parent.dotManager.ApplyStopElement(element);
		}
	}

	public void BaseOnEnter()
	{
		SetRepeatLock();
		SetSkillSlot();
		if (parent.skillEnterEventHandlers != null)
		{
			parent.skillEnterEventHandlers(this);
		}
		if (fsm.previousState is SkillState)
		{
			prevSkillState = fsm.previousState as SkillState;
			if (isBasic)
			{
				if (!prevSkillState.isBasic && parent.cancelToBasicEventHandlers != null)
				{
					parent.cancelToBasicEventHandlers(this, prevSkillState);
				}
			}
			else if (prevSkillState.isBasic && parent.cancelFromBasicEventHandlers != null)
			{
				parent.cancelFromBasicEventHandlers(this, prevSkillState);
			}
			else if (isDash && parent.cancelToDashEventHandlers != null)
			{
				parent.cancelToDashEventHandlers(this, prevSkillState);
			}
		}
		cdStarted = false;
		if (!disableStartCooldown && startCooldownOnEnter)
		{
			StartCooldownTimer();
		}
		if (applyStopElementStatus)
		{
			ApplyStopElement();
		}
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		inputVector = parent.GetInputVector();
		parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
		holdStarted = false;
		holdReleased = false;
		skillExecuted = false;
	}

	public override void Update()
	{
		UpdateRepeatLock(string.Empty);
		if (skillExecuted)
		{
			ConcludeSkill();
		}
		else if (isHoldSkill)
		{
			if (holdReleased)
			{
				ExecuteSkill();
			}
			else if (holdStarted)
			{
				HandleHoldButton();
			}
			else
			{
				holdStarted = parent.anim.AnimPlayed(animHoldTime);
			}
		}
		else if (parent.anim.AnimPlayed(animExecTime))
		{
			ExecuteSkill();
		}
	}

	public virtual void HandleHoldButton()
	{
		inputVector = GetInputVector();
		if (updateHoldAnim)
		{
			parent.anim.PlayDirectional(OnHoldAnimStr, -1, animHoldTime);
		}
		holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
	}

	public virtual void ExecuteSkill()
	{
		skillExecuted = true;
		AnnounceSkillExecuteEvent();
	}

	public virtual void AnnounceSkillExecuteEvent()
	{
		if (parent.skillExecEventHandlers != null)
		{
			parent.skillExecEventHandlers(this);
		}
	}

	public virtual void ConcludeSkill()
	{
		ExitToSkillOrRunOrIdle();
	}

	public override void OnExit()
	{
		if (allowSelfTransition && !allowRepeating && GetType() != fsm.nextState.GetType())
		{
			SetRepeatLock(setLock: false);
		}
		if (!disableStartCooldown && !startCooldownOnEnter)
		{
			StartCooldownTimer();
		}
		if (parent.skillExitEventHandlers != null)
		{
			parent.skillExitEventHandlers(this);
		}
	}

	public void SetSkillLevel(int skillLevel)
	{
		currentLevel = skillLevel;
		skillData.currentLevel = skillLevel;
	}

	public Vector2 GetInputVector(bool faceInputVector = true, bool useAimVector = true, bool ignoreZero = true)
	{
		return parent.GetInputVector(faceInputVector, useAimVector, ignoreZero);
	}

	public bool CancelToDash(bool enableButtonHeld = false)
	{
		cancelToDashSkill = parent.GetDashSkill();
		return cancelToDashSkill != null && parent.TransitionToSkill(cancelToDashSkill.SetSkillSlot(), enableButtonHeld);
	}

	public bool CancelToSkills(bool overrideThresholdReq = false)
	{
		return (overrideThresholdReq || parent.anim.AnimPlayed(cancelThreshold)) && parent.HandleSkills(allowButtonHeld: true, string.Empty);
	}

	public virtual bool ExitToSkillOrRunOrIdle()
	{
		currentAnimTime = parent.anim.GetAnimTime();
		if (currentAnimTime >= cancelThreshold && parent.HandleSkills(allowButtonHeld: true, string.Empty))
		{
			return true;
		}
		if (currentAnimTime >= runThreshold && GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false) != Vector2.zero)
		{
			fsm.ChangeState("Run");
			return true;
		}
		if (currentAnimTime >= exitThreshold)
		{
			fsm.ChangeState(fsm.defaultStateName);
			return true;
		}
		return false;
	}

	public T ChaosInst<T>(GameObject givenPrefab, Vector2? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTransform = null)
	{
		return Globals.ChaosInst<T>(givenPrefab, parentTransform ?? parent.transform.parent, (!givenPosition.HasValue) ? ((Vector2)parent.attackOriginTrans.position) : givenPosition.Value, (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value);
	}

	public void SetTargetLineVars(bool groundBased = true, bool stopOnDestructible = true, bool stopOnEnemy = true)
	{
		parent.targetLine.SetCollisionLayerMask((!groundBased) ? "TargetLineAir" : "TargetLineGround", stopOnDestructible, stopOnEnemy, (skillData != null) ? skillData.GetValue<List<string>>("targetNames") : null);
	}

	public void SetAttackInfo(Attack givenAtk)
	{
		givenAtk.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
	}
}

public class PausedState : State<Player>
{
	public PausedState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
	}

	public override void OnEnter()
	{
		parent.movement.EndMovement();
		parent.isFacingRight = parent.facingDirection != FacingDirection.Left;
		parent.anim.PlayDirectional("Idle" + parent.facingDirection);
	}
}

public class IdleState : State<Player>
{
	public IdleState(string stateName, FSM parentFSM, Player parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
	}

	public override void OnEnter()
	{
		parent.isFacingRight = parent.facingDirection != FacingDirection.Left;
		parent.anim.PlayDirectional(name + parent.facingDirection);
	}

	public override void Update()
	{

public class BaseDashState : SkillState
{
	public bool showEffects = true;

	public bool playSFX = true;

	public bool cooldownReady;

	public bool prevCDWasReady;

	public bool finishedDashing;

	public float dashDuration = 0.125f;

	public NumVarStatMod dashDurationMod;

	public BoolVarStat forceEvadeStat;

	public NumVarStatMod evadeMod;

	public BoolVarStatMod airborneMod;

	public BaseDashState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isDash = true;
		isMovementSkill = true;
		forceEvadeStat = new BoolVarStat(newBaseVal: false);
		evadeMod = new NumVarStatMod("DashEvade", 1f, 10, VarStatModType.Override);
		airborneMod = new BoolVarStatMod(SkillState.staticID, newModValue: true);
		dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
	}

	public override bool IsReady()
	{
		return parent.MovementEnabled && (!allowSelfTransition || allowRepeating || !repeatLock) && (!isUltimate || IsOverdriveReady());
	}

	public override void OnEnter()
	{
		if (parent.dashSlideIgnored)
		{
			cooldownReady = prevCDWasReady;
			disableStartCooldown = true;
		}
		else
		{
			cooldownReady = cooldownRef.Ready;
			prevCDWasReady = cooldownReady;
			disableStartCooldown = !cooldownReady;
		}
		parent.dashSlideIgnored = false;
		BaseOnEnter();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.AddMod(evadeMod);
		}
		finishedDashing = false;
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDuration;
		if (parent.inputDevice == null)
		{
			inputVector = Vector2.zero;
		}
		else if (parent.inputDevice.IsMouseDash)
		{
			inputVector = GetInputVector();
		}
		else
		{
			inputVector = GetInputVector(faceInputVector: true, (parent.inputDevice.inputScheme == ChaosInputDevice.InputScheme.Gamepad && ChaosInputDevice.lockControllerAim) ? true : false);
		}
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		if (showEffects && !cooldownReady)
		{
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
			parent.dustEmitter.EmitDirBurst(15, Globals.GetRotationVector(-inputVector).z);
			parent.dashTrails.SetActive(value: true);
		}
		if (playSFX)
		{
			SoundManager.PlayWithDistAndSPR("StandardDash", parent.transform.position);
		}
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.airborneStat.AddMod(airborneMod);
		AnnounceSkillExecuteEvent();
	}

	public override void Update()
	{
		if (finishedDashing)
		{
			ExitTransition();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			finishedDashing = parent.movement.DashToTarget();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
		DashFinished();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.RemoveMod(evadeMod);
		}
	}

	public virtual void DashFinished()
	{
		parent.dashTrails.SetActive(value: false);
		parent.TogglePreventFallCollider(status: true);
		parent.airborneStat.RemoveMod(airborneMod);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.EndMovement();
	}

	public virtual void ExitTransition()
	{
		fsm.ChangeState(SlideState.staticID);
	}
}

public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;

	protected Vector2 startPosition;

	protected bool useCalcValues;

	protected float jumpRange = 5.5f;

	protected float jumpSpeed = 32f;

	protected float jumpTime = 0.5f;

	protected float jumpHeight = 1f;

	protected float jumpBalance = 0.5f;

	protected bool hasLanded;

	protected bool collidersEnabled;

	protected float landingDelay;

	protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch();

	public bool setInputVectorOnEnter = true;

	protected BoolVarStatMod airborneStatMod;

	public BaseJumpState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		parentThrow = parent.throwScript;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		if (setInputVectorOnEnter)
		{
			inputVector = GetInputVector();
		}
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst));
		landingStopwatch.SetDelay(landingDelay);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
	}

	public override void Update()
	{
		if (hasLanded)
		{
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				ToggleObjects(status: true);
			}
			if (!landingStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}

	public override void OnExit()
	{
		if (!hasLanded)
		{
			OnLanding();
		}
		base.OnExit();
		ToggleObjects(status: true);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}

	public virtual void OnLanding()
	{
		hasLanded = true;
		landingStopwatch.IsRunning = true;
		parent.spriteRenderer.sortingLayerName = "Actor";
	}

	public virtual void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		if (parent.hurtBoxObj != null && parent.hurtBoxObj.activeSelf != status)
		{
			parent.hurtBoxObj.SetActive(status);
		}
		if (parent.floorContact != null && parent.floorContact.activeSelf != status)
		{
			parent.floorContact.SetActive(status);
		}
		parent.TogglePreventFallCollider(status);
	}

	public virtual void SetThrowValues()
	{
		parentThrow.useCalculatedValues = useCalcValues;
		parentThrow.moveSpeed = jumpSpeed;
		parentThrow.baseFlightTime = jumpTime;
		parentThrow.throwHeight = jumpHeight;
		parentThrow.isFallingThreshold = jumpBalance;
	}
}

