			PoolManager.GetPoolItem<ParticleEffect>("ReflectEffect").Emit(1, otherScript.transform.position - (Vector3)otherScript.moveVector * 0.66f, new ParticleSystemOverride
			{
				localEulerAngles = Globals.GetRotationVector(otherScript.moveVector)
			});
			SoundManager.PlayAudioWithDistance("ImpactReflect", transform.position);
			if (globalReflectEventHandlers != null)
			{
				globalReflectEventHandlers(this, other, otherScript, skillCategory);
			}
		}
	}

	private Vector2 GetReflectedMoveVector(Projectile other)
	{
		if (givenNormal == Vector2.zero)
		{
			givenNormal = (other.transform.position - transform.position).normalized;
		}
		return Vector2.Reflect(other.moveVector, givenNormal).normalized;
	}
}

	public class UseRockThrowBasic : MeleeAttackState
	{
		public new static string staticID = "UseRockThrowBasic";

		private RockThrowProjectile currentRT;

		private bool secondaryFired;

		private bool isDoubleShot;

		private bool DoubleShot => IsEmpowered && comboCounter != maxComboCount && (!repeatFinalHit || comboCounter != maxComboCount - 1);

		public UseRockThrowBasic(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			isBasic = true;
			isProjectileSkill = true;
			attackPrefab = RockThrowProjectile.Prefab;
			setParent = false;
			destroyAttackObjectOnExit = false;
			maxComboCount = 3;
			animStartTime = 0.1f;
			animExecTime = 0.25f;
			baseCancelThreshold = 0.45f;
			finalCancelThreshold = 0.4f;
			baseRunThreshold = 0.6f;
			finalRunThreshold = 0.75f;
			baseExitThreshold = 0.9f;
			finalExitThreshold = 0.9f;
			finalAttackScale = 1.5f;
			flipObjectForBackhand = false;
			attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 6f, 10, VarStatModType.OverrideWithMods);
			finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 8f, 10, VarStatModType.OverrideWithMods);
			sfxNames = new string[maxComboCount];
			for (int i = 0; i < maxComboCount; i++)
			{
				sfxNames[i] = "RockThrowBasic";
			}
			autoHoldStat.BaseValue = true;
		}

		public override void PlayAnimation(int attackCount)
		{
			switch (comboCounter)
			{
			case 1:
				parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, animStartTime);
				break;
			case 2:
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animStartTime);
				break;
			case 3:
				parent.anim.PlayDirectional(parent.KickAnimStr, -1, animStartTime);
				break;
			default:
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animStartTime);
				break;
			}
		}

		public override void OnEnter()
		{
			base.OnEnter();
			isDoubleShot = DoubleShot;
			if (isDoubleShot)
			{
				secondaryFired = false;
				animExecTime = 0.2f;
			}
			else
			{
				animExecTime = 0.25f;
			}
		}

		public override void ExecuteAttack()
		{
			parent.movement.EndMovement();
			HandleComboCount(comboCounter);
			HandleSelfTransition(comboCounter);
			AnnounceSkillExecuteEvent();
			CreateRockThrow();
			if (isDoubleShot && !secondaryFired)
			{
				secondaryFired = true;
				attackExecuted = false;
				animExecTime = 0.35f;
			}
		}

		private void CreateRockThrow()
		{
			currentRT = (RockThrowProjectile)Projectile.CreateProjectile(parent, attackPrefab, (Vector2)parent.attackOriginTrans.position + inputVector * 0.25f);
			currentRT.moveVector = inputVector;
			currentRT.attackBox.SetAttackInfo(parent.skillCategory, skillID, currentLevel);
			currentRT.attackBox.knockbackOverwriteVector = inputVector;
			currentRT.SetSprite((calcComboCounter == 0) ? 1 : 0);
			currentRT.attackBox.transform.localScale = calcScaleVector * scaleValue;
			PoolManager.GetPoolItem<DashAirBurst>().Burst(currentRT.transform.position + (Vector3)inputVector, inputVector, useOffset: false);
			RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
			RockDebrisType debrisType = RockDebrisType.Default;
			int? particleCount = 3;
			Vector3? position = currentRT.transform.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
			poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			if (isDoubleShot)
			{
				currentRT.attackBox.atkInfo.damage = Mathf.CeilToInt((float)currentRT.attackBox.atkInfo.damage * 0.6f);
			}
		}
	}

