public virtual void Awake()
{
	anim = GetComponent<Animator>();
	rigidbody2D = GetComponent<Rigidbody2D>();
	attackBox = base.transform.GetComponentInChildren<Attack>();
	if (attackBox != null)
	{
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(HandleCollision));
	}
	collidedProjectiles = new List<Projectile>();
	projectileSprite = base.transform.Find("ProjectileSprite").gameObject;
	projectileSpriteRenderer = projectileSprite.GetComponent<SpriteRenderer>();
	if (base.transform.Find("ProjectileLight") != null)
	{
		projectileLight = base.transform.Find("ProjectileLight").gameObject;
	}
	if (pointTowardMoveVector)
	{
		Hide();
	}
	OffsetSortingLayer();
	thickness = 0f;
	Transform transform = base.transform.Find("WallCollider");
	if (transform != null)
	{
		CircleCollider2D component = transform.gameObject.GetComponent<CircleCollider2D>();
		if (component != null)
		{
			thickness = component.radius * ((!(base.transform.localScale.x > base.transform.localScale.y)) ? base.transform.localScale.y : base.transform.localScale.x);
			wallCollider = component;
		}
		else
		{
			BoxCollider2D component2 = transform.gameObject.GetComponent<BoxCollider2D>();
			if (component2 != null)
			{
				thickness = component2.size.x * base.transform.localScale.x;
				wallCollider = component2;
			}
		}
	}
	if (thickness > 0f && (double)thickness < 0.0625)
	{
		thickness = 0.0625f;
	}
}

public virtual void InitTimers()
{
	flyStopwatchID = ChaosStopwatch.Begin(flyTime);
	lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
}

public virtual void Start()
{
	if (parentObject != null && parentEntity == null)
	{
		parentEntity = parentObject.GetComponentInParent<Entity>();
	}
	InitTimers();
	startAttackBoxDamageOverride = attackBox.damageOverride;
	UpdateCalculatedDamage(initDamageOverride: true);
	rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f);
	if (projectileSpawnEvent != null)
	{
		projectileSpawnEvent(this);
	}
}

public void Show()
{
	visualsOn = true;
	projectileSpriteRenderer.enabled = true;
	if (projectileLight != null)
	{
		projectileLight.SetActive(value: true);
	}
}

public void Hide()
{
	visualsOn = false;
	projectileSpriteRenderer.enabled = false;
	if (projectileLight != null)
	{
		projectileLight.SetActive(value: false);
	}
}

private void OnEnable()
{
	targetGroup = GameController.enemies;
	InitTimers();
}

private void OnDisable()
{
	CallOnDisable();
}

public virtual void CallOnDisable()
{
	moveVector = Vector2.zero;
	isPointedAtMoveVector = false;
}

public virtual bool CheckMaxLifeTime()
{
	if (ChaosStopwatch.Check(lifeStopwatchID) || flagForReset)
	{
		ResetProjectile();
		return true;
	}
	return false;
}

public virtual void Update()
{
	if (!shootAnnounced && moveSpeed > 0f && moveVector != Vector2.zero && projectileShootEvent != null)
	{
		projectileShootEvent(this);
		shootAnnounced = true;
	}
	if (CheckMaxLifeTime())
	{
		return;
	}
	if (ChaosStopwatch.Check(flyStopwatchID))
	{
		if (!boomerang)
		{
			ResetProjectile();
			return;
		}
		if (parentObject == null)
		{
			boomerang = false;
			Debug.Log(gameObject.name + " has no parent, but is set to boomerang.");
			return;
		}
		if (!boomerangReturning)
		{
			boomerangReturning = true;
			OnBoomerangReturn();
			return;
		}
		if (attackBox != null && resetAttackOnBoomerangReturn)
		{
			attackBox.gameObject.SetActive(value: true);
		}
		HandleBoomerang();
	}
	if (boomerangReturning && (parentObject == null || Vector2.Distance(transform.position, parentObject.transform.position) < returningSnapDistance))
	{
		ResetProjectile();
	}
}

public virtual void FixedUpdate()
{
	if (updateVelocity)
	{
		rigidbody2D.velocity = moveVector * moveSpeed;
	}
	HandleRotation();
	HandlePointTowardMoveVector();
}

public virtual void HandleRotation()
{
	if (rotation)
	{
		projectileSprite.transform.Rotate(rotationVector * Time.fixedDeltaTime);
	}
}

public void HandlePointTowardMoveVector()
{
	if (pointTowardMoveVector && moveVector != Vector2.zero && !isPointedAtMoveVector)
	{
		Vector2 targetPosition = ((!flipPointTowardMoveVector) ? ((Vector2)transform.position + moveVector) : ((Vector2)transform.position - moveVector));
		RotateTowardsTarget(targetPosition);
		isPointedAtMoveVector = true;
	}
	if (pointTowardMoveVector && isPointedAtMoveVector && !visualsOn)
	{
		Show();
	}
}

public bool IsParentObject(GameObject other)
{
	Entity componentInParent = other.GetComponentInParent<Entity>();
	return other == parentObject || other.transform.parent.gameObject == parentObject || (componentInParent != null && componentInParent.skillCategory == attackBox.atkInfo.skillCategory) || (parentEntity != null && componentInParent == parentEntity);
}

public virtual void OnTriggerEnter2D(Collider2D other)
{
	HandleProjectileCollision(other);
}

public virtual void HandleProjectileCollision(Collider2D other)
{
	colProj = other.GetComponentInParent<Projectile>();
	if (!(colProj == null) && !ignoreProjectileCollisions && !colProj.ignoreProjectileCollisions && !collidedProjectiles.Contains(colProj) && attackBox.atkInfo != null && colProj.attackBox.atkInfo != null && !(attackBox.atkInfo.skillCategory == colProj.attackBox.atkInfo.skillCategory) && (GameController.pvpOn || !(parentEntity is Player) || !(colProj.parentEntity is Player)))
	{
		OnProjectileCollision(other, colProj);
		if (globalProjectileCollisionEvents != null)
		{
			globalProjectileCollisionEvents(this, colProj);
		}
		PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Large, other.transform.position, attackBox.transform.position);
		CameraController.ShakeCamera(0.25f);
	}
}

public virtual void UpdateCalculatedDamage(bool initDamageOverride = false)
{
	if (initDamageOverride)
	{
		attackBox.damageOverride = startAttackBoxDamageOverride;
	}
	projectileStatData = StatManager.GetSkillData(attackBox.atkInfo.skillCategory, attackBox.atkInfo.skillID);
	if (projectileStatData != null)
	{
		calculatedDamage = (int)(projectileCollisionModifier * (float)((attackBox.damageOverride >= 0) ? attackBox.damageOverride : ((attackBox.atkInfo != null) ? attackBox.atkInfo.damage : Mathf.FloorToInt(projectileStatData.GetValue<int>(StatData.damageStr)))));
	}
}

public virtual void OnBoomerangReturn()
{
	if (attackBox != null && resetAttackOnBoomerangReturn)
	{
		attackBox.gameObject.SetActive(value: false);
		UpdateCalculatedDamage(initDamageOverride: true);
	}
}

public virtual void HandleBoomerang()
{
	if (parentObject != null)
	{
		moveVector = (parentObject.transform.position - transform.position).normalized;
	}
}

public virtual void OnProjectileCollision(Collider2D other, Projectile otherProjectile, bool doCalculations = true)
{
	if (doCalculations)
	{
		if (!alwaysWinCollision && !otherProjectile.alwaysWinCollision)
		{
			calcDamageDiff = calculatedDamage - otherProjectile.calculatedDamage;
			otherProjectile.calculatedDamage = Mathf.Max(0, otherProjectile.calculatedDamage - calculatedDamage);
			calculatedDamage = Mathf.Max(0, calcDamageDiff);
		}
		else
		{
			if (alwaysWinCollision)
			{
				otherProjectile.calculatedDamage = 0;
			}
			if (otherProjectile.alwaysWinCollision)
			{
				calculatedDamage = 0;
			}
		}
		otherProjectile.OnProjectileCollision(other, this, doCalculations: false);
	}
	if (calculatedDamage < 10 && (!alwaysWinCollision || otherProjectile.alwaysWinCollision))
	{
		calculatedDamage = 0;
		HandleCollision(other);
	}
	calcDamageActual = Mathf.CeilToInt((float)calculatedDamage / projectileCollisionModifier);
	attackBox.damageOverride = ((projectileStatData == null || projectileStatData.GetValue<int>("damage") <= calcDamageActual) ? (-1) : calcDamageActual);
	collidedProjectiles.Add(otherProjectile);
	SoundManager.PlayAudioWithDistance("ImpactNegate", transform.position);
}

public virtual void HandleWallCollision(Collider2D other)
{
	if (wallCollider != null)
	{
		PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, wallCollider.transform.position, wallCollider.transform.position);
	}
	else
	{
		PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, transform.position, transform.position);
	}
	if (!goThroughWalls)
	{
		if (boomerang)
		{
			ChaosStopwatch.Stop(flyStopwatchID);
		}
		else
		{
			ResetProjectile();
		}
	}
	if (globalProjectileWallCollisionEvents != null)
	{
		globalProjectileWallCollisionEvents(this);
	}
	if (wallCollisionEvents != null)
	{
		wallCollisionEvents(this);
	}
	HandleCollision(other);
}

public virtual void HandleCollision(Collider2D other)
{
	if (!(other.transform.parent != null) || IsParentObject(other.gameObject))
	{
		return;
	}
	if (impactAudioID != string.Empty)
	{
		SoundManager.PlayAudioWithDistance(impactAudioID, transform.position);
	}
	if (disableOnHit || calculatedDamage == 0)
	{
		flagForReset = true;
	}
	else if (returnOnHit)
	{
		ChaosStopwatch.Stop(flyStopwatchID);
	}
	else if (ricochet && ricochetAmount > 0 && !boomerangReturning)
	{
		ricochetCounter++;
		boomerangReturning = false;
		TargetsHitList.Add(other.transform.parent.gameObject);
		nextTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, ricochetRadius, playerTagOnly: false, TargetsHitList, null, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
		if (ricochetCounter >= ricochetAmount || nextTargetInfo == null)
		{
			ChaosStopwatch.Stop(flyStopwatchID);
			ricochetCounter = 0;
			return;
		}
		OnRicochet();
		ChaosStopwatch.Refresh(flyStopwatchID, flyTime);
		moveVector = (nextTargetInfo.hurtBoxPosition - transform.position).normalized;
		isPointedAtMoveVector = false;
	}
}

public virtual void ResetProjectile()
{
	ChaosStopwatch.Stop(flyStopwatchID);

