using Chaos.AnimatorExtensions;
using UnityEngine;

public class VinePull : MonoBehaviour
{
	private static GameObject _prefab;

	public Animator anim;

	public FollowTransform followTrans;

	[HideInInspector]
	public Transform targetTrans;

	[HideInInspector]
	public Vector3 targetPos;

	private bool initialized;

	private bool pullAnimStarted;

	private bool destroyQueued;

	private bool lostTarget;

	private bool isSmallVer;

	private bool isEmpowered;

	private bool resetAfterAtk = true;

	public bool stopRotateOnPull;

	private bool useScaledKnockback = true;

	private AttackGeneric curGenAtk;

	private string skillCat;

	private string skillID;

	private int skillLevel;

	[HideInInspector]
	public float maxDist = 4.25f;

	private Vector2 pullKnockbackOffset;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/VinePull.prefab");
			}
			return _prefab;
		}
	}

	public static Vector2 GetRandVineTargetPos(Vector2 originPos, Vector2 moveVec)
	{
		return originPos - moveVec * 4f + Random.insideUnitCircle * 4f;
	}

	private void Start()
	{
		if (!initialized)
		{
			gameObject.SetActive(value: false);
		}
	}

	private void Reset()
	{
		initialized = false;
		pullAnimStarted = false;
		destroyQueued = false;
		lostTarget = false;
		isSmallVer = false;
		isEmpowered = false;
		resetAfterAtk = true;
		skillLevel = 0;
		pullKnockbackOffset = Vector2.zero;
		followTrans.followTransform = null;
		followTrans.followOffset = Vector3.zero;
		targetTrans = null;
		transform.localEulerAngles = Vector3.zero;
		anim.Play("Idle", -1, 0f);
		gameObject.SetActive(value: false);
	}

	public void Initialize(Transform givenFollowTrans, Transform givenTargetTrans, Vector3 givenTargetPos, Vector2 followOffset, Vector2 pullKBOffset, string givenSkillCat, string givenSkillID, int givenSkillLevel, bool givenEmpowered)
	{
		gameObject.SetActive(value: true);
		followTrans.followTransform = givenFollowTrans;
		followTrans.followOffset = followOffset;
		targetPos = givenTargetPos;
		if (givenTargetTrans != null)
		{
			targetTrans = givenTargetTrans;
		}
		RotateTowardTarget();
		if ((double)Random.value > 0.5)
		{
			transform.localScale = new Vector3(0f - transform.localScale.x, transform.localScale.y, transform.localScale.z);
		}
		isEmpowered = givenEmpowered;
		skillCat = givenSkillCat;
		skillID = givenSkillID;
		skillLevel = givenSkillLevel;
		pullKnockbackOffset = pullKBOffset;
		if (!lostTarget)
		{
			anim.Play("Spawn", -1, 0f);
			CreateAttack();
		}
		else
		{
			anim.Play("SpawnSmall", -1, 0f);
			isSmallVer = true;
		}
		skillLevel++;
		initialized = true;
	}

	private void RotateTowardTarget()
	{
		if (!pullAnimStarted || !stopRotateOnPull)
		{
			if (targetTrans == null || followTrans == null || followTrans.followTransform == null || transform == null)
			{
				lostTarget = true;
			}
			if (!lostTarget)
			{
				targetPos = targetTrans.position;
			}
			if (followTrans != null && followTrans.followTransform != null)
			{
				transform.localEulerAngles = Globals.GetRotationVector(targetPos - followTrans.followTransform.position);
			}
		}
	}

	private void CreateAttack()
	{
		curGenAtk = PoolManager.GetPoolItem<AttackGeneric>();
		curGenAtk.attack.SetAttackInfo(skillCat, skillID, skillLevel);
		curGenAtk.attack.knockbackOverwriteVector = followTrans.followTransform.position - targetTrans.position;
		if (useScaledKnockback)
		{
			curGenAtk.attack.atkInfo.knockbackMultiplier = Vector2.Distance(followTrans.followTransform.position, targetTrans.position) * 7.5f;
		}
		curGenAtk.CircleAttack(targetTrans.position, 0.01f);
	}

	private void Retract()
	{
		if (!lostTarget)
		{
			if (!isSmallVer && isEmpowered)
			{
				skillLevel++;
			}
			CreateAttack();
		}
		if (isSmallVer)
		{
			anim.Play("RetractSmall", -1, 0f);
		}
		else
		{
			anim.Play("Retract", -1, 0f);
		}
		pullAnimStarted = true;
	}

	private void Update()
	{
		if (!initialized || destroyQueued)
		{
			return;
		}
		RotateTowardTarget();
		if (!pullAnimStarted)
		{
			if (anim.AnimPlayed())
			{
				Retract();
			}
		}
		else if (anim.AnimPlayed())
		{
			if (!lostTarget && !isSmallVer && isEmpowered)
			{
				skillLevel++;
				CreateAttack();
			}
			if (!resetAfterAtk)
			{
				destroyQueued = true;
				Object.Destroy(gameObject, 1f);
			}
			else
			{
				Reset();
			}
		}
	}
}
