public class PoisonBomb : ThrownItem
{
	private static GameObject prefab;

	[HideInInspector]
	public Attack attackBox;

	[HideInInspector]
	public PoisonType poisonType;

	[HideInInspector]
	public bool useCastingCircle = true;

	private CastingCircle castingCircle;

	private bool castingCircleReset;

	public float explosionDelay = 1f;

	private int delayStopwatchID;

	public float poisonDuration = 3f;

	private int durationStopwatchID;

	public float attackRadius = 2f;

	private CircleCollider2D atkCollider;

	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(5f);

	private PoisonCircle poisonCircle;

	private bool poisonStarted;

	private bool poisonComplete;

	private bool openAnimPlayed;

	private PoisonEffect poisonEffect;

	private Transform shadowTrans;

	private AudioSource gasAudioSource;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/ThrownItems/PoisonBomb.prefab"));

	public override void Awake()
	{
		base.Awake();
		attackBox = transform.Find("AttackBox").GetComponent<Attack>();
		atkCollider = attackBox.GetComponent<CircleCollider2D>();
		spriteTrans = transform.Find("ItemSprite");
		spriteRenderer = spriteTrans.GetComponent<SpriteRenderer>();
		shadowTrans = transform.Find("ShadowSprite");
		landedHeight = spriteTrans.localPosition.y;
	}

	public override void Start()
	{
		base.Start();
		atkCollider.radius = attackRadius;
	}

	public override void Update()
	{
		if (!throwComplete)
		{
			return;
		}
		if (!poisonStarted)
		{
			if (!openAnimPlayed && ChaosStopwatch.GetRemainingTime(delayStopwatchID) <= 0.15f)
			{
				openAnimPlayed = true;
				anim.Play("Open", -1, 0f);
				PoolManager.GetPoolItem<LeafEmitter>("FallingLeafBurstEmitter").EmitSingle(3, transform.position + Vector3.up);
				poisonEffect = Object.Instantiate(PoisonEffect.Prefab, transform.position, Quaternion.identity).GetComponent<PoisonEffect>();
				poisonEffect.prewarm = false;
			}
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				poisonStarted = true;
				CameraController.ShakeCamera(0.25f);
				Object.Destroy(poisonEffect.gameObject);
				StartPoison();
				return;
			}
		}
		if (!poisonComplete && ChaosStopwatch.Check(durationStopwatchID))
		{
			poisonComplete = true;
			StopPoison();
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (poisonStarted)
		{
			if (atkStopwatch.IsRunning)
			{
				atkCollider.enabled = true;
				return;
			}
			atkStopwatch.IsRunning = true;
			atkCollider.enabled = false;
		}
	}

	public override void OnLanding()
	{
		destroyTime = poisonDuration + explosionDelay;
		base.OnLanding();
		delayStopwatchID = ChaosStopwatch.Begin(explosionDelay);
		durationStopwatchID = ChaosStopwatch.Begin(destroyTime);
		if (useCastingCircle)
		{
			castingCircle = CastingCirclePool.Spawn("Draw", transform.position, parentObj: gameObject, unitSizeY: attackRadius, color: CastingCircle.enemyColor, drawTime: explosionDelay, disableWithParentVal: true, trackParentVal: true, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: attackRadius);
		}
		anim.Play("Idle", -1, 0f);
	}

	private void StartPoison()
	{
		atkCollider.enabled = true;
		poisonCircle = PoolManager.GetPoolItem<PoisonCircle>();
		poisonCircle.Play(transform.position, attackRadius, poisonType);
		SoundManager.PlayAudioWithDistance("ExplosionPop", transform.position);
		gasAudioSource = SoundManager.PlayAudioWithDistance("GasEscape", transform.position);
		if (castingCircle != null)
		{
			castingCircle.Reset();
			castingCircleReset = true;
		}
	}

	private void OnDestroy()
	{
		StopPoison();
	}

	private void StopPoison()
	{
		if (castingCircle != null && !castingCircleReset)
		{
			castingCircle.Reset();
		}
		if (gasAudioSource != null)
		{
			gasAudioSource.Stop();
		}
		atkCollider.enabled = false;
		if (poisonCircle != null)
		{
			poisonCircle.Stop();
		}
		shadowTrans.gameObject.SetActive(value: false);
	}

	public override void HandleRotateSprite()
	{
		if (rotateSprite)
		{
			spriteTrans.transform.localEulerAngles = Vector3.Lerp(startRotation, endRotation, percentComplete + 0.25f);
		}
	}
}
