	public bool hitIntervalRunning;

	private int hitStopwatchID;

	public int hitCount = 5;

	public float hitInterval = 0.125f;

	[HideInInspector]
	public bool isMega;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthDrill.prefab"));

	public static ParticleSystemOverride DebrisEffectSettings
	{
		get
		{
			if (_debrisEffectSettings == null)
			{
				_debrisEffectSettings = new ParticleSystemOverride();
				_debrisEffectSettings.radius = 1.5f;
				_debrisEffectSettings.startLifetime = 0.6f;
				_debrisEffectSettings.startSpeed = 7f;
				_debrisEffectSettings.emissionRate = 20f;
			}
			return _debrisEffectSettings;
		}
	}

	public static ParticleSystemOverride MegaDebrisEffectSettings
	{
		get
		{
			if (_megaDebrisEffectSettings == null)
			{
				_megaDebrisEffectSettings = new ParticleSystemOverride();
				_megaDebrisEffectSettings.radius = 2.25f;
				_megaDebrisEffectSettings.startLifetime = 0.6f;
				_megaDebrisEffectSettings.startSpeed = 8f;
				_megaDebrisEffectSettings.emissionRate = 28f;
			}
			return _megaDebrisEffectSettings;
		}
	}

	public void Awake()
	{
		anim = GetComponent<Animator>();
		rigidbody2D = GetComponent<Rigidbody2D>();
		attack = transform.Find("AttackBox").GetComponent<Attack>();
		spriteSorter = transform.Find("Sprite").GetComponent<SortSpriteLayer>();
	}

	public void Start()
	{
		if (isMega)
		{
			anim.Play("MegaSpawn", -1, 0f);
			PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect").Emit(24, transform.position + followOffset * 0.75f, RockFormEffect.MedSettings);
			rockDebrisEffect = PoolManager.GetPoolItem<RockDebrisEmitter>();
			rockDebrisEffect.PlaySingle(7f, transform.position, MegaDebrisEffectSettings, followTransform: transform, playTime: 5f);
		}
		else
		{
			anim.Play("Spawn", -1, 0f);
			PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect").Emit(10, transform.position, RockFormEffect.MedSettings);
			rockDebrisEffect = PoolManager.GetPoolItem<RockDebrisEmitter>();
			rockDebrisEffect.PlaySingle(5f, transform.position, DebrisEffectSettings, followTransform: transform, playTime: 5f);
		}
		if (drillAudio == null || !drillAudio.isPlaying)
		{
			drillAudio = SoundManager.PlayAudioWithDistance("Drill", transform.position);
		}
	}

	public void Activate()
	{
		if (isMega)
		{
			anim.Play("MegaSpin", -1, 0f);
		}
		else
		{
			anim.Play("Spin", -1, 0f);
		}
	}

	public void Deactivate()
	{
		if (isMega)
		{
			anim.Play("MegaIdle", -1, 0f);
		}
		else
		{
			anim.Play("Idle", -1, 0f);
		}
		if (rockDebrisEffect != null)
		{
			rockDebrisEffect.Stop();
		}
	}

	public void StartInterval()
	{
		hitIntervalRunning = true;
		hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, hitCount);
	}

	private void FixedUpdate()
	{
		if (followTransform != null)
		{
			transform.position = followTransform.position + followOffset;
		}
		if (hitIntervalRunning)
		{
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Running:
				attack.gameObject.SetActive(value: true);
				break;
			case StopwatchState.Ready:
				attack.gameObject.SetActive(value: false);
				break;
			case StopwatchState.Done:
				Deactivate();
				hitIntervalRunning = false;
				attack.gameObject.SetActive(value: true);
				break;
			}
		}
	}

	public void Reset()
	{
		Vector3 vector;
		if (isMega)
		{
			vector = transform.position + followOffset * 0.25f;
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(8, vector, RockDebrisEmitter.MedCircleExplosionOverride);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(6, vector, RockDebrisEmitter.MedCircleExplosionOverride);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, vector, RockDebrisEmitter.MedCircleExplosionOverride);
		}
		else
		{
			vector = transform.position + spriteSorter.transform.TransformPoint(Vector3.up).normalized;
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(6, vector, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, vector, RockDebrisEmitter.SmallCircleExplosionOverride);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(1, vector, RockDebrisEmitter.SmallCircleExplosionOverride);
		}
		Deactivate();
		if (drillAudio != null && drillAudio.isPlaying)
		{
			drillAudio.Stop();
		}
		SoundManager.PlayAudioWithDistance("EarthPebble", vector);
		SoundManager.PlayAudioWithDistance("RockExplode", vector);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 4;
		Vector3? emitPosition = transform.position;
		poolItem.EmitDirBurst(particleCount, 0f, -1f, -1f, -1f, emitPosition);
		if (rockDebrisEffect != null)
		{
			rockDebrisEffect.Stop();
		}
		Object.Destroy(gameObject);
	}

	public void PlayFormAudio()
	{
		string audioID = "RockFormShort";
		Vector2? soundOrigin = transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
	}
}

