	public class UseShatterStone : SkillState
	{
		public new static string staticID = "UseShatterStone";

		private ChaosQuickStopwatch summonStopwatch = new ChaosQuickStopwatch(0.125f);

		private ChaosQuickStopwatch kickStopwatch = new ChaosQuickStopwatch(0.0625f);

		private ShatterStone currentSS;

		private Vector2 spawnPosition;

		private bool summonComplete;

		private bool kickDelayComplete;

		private bool shatterComplete;

		private string animString;

		private static int ultShatterCount = 3;

		private int ultCounter;

		public UseShatterStone(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			isMeleeSkill = true;
			SetAnimTimes(0f, 0.2f, 0.3f, 0.8f, 0.9f);
		}

		public override void OnEnter()
		{
			BaseOnEnter();
			base.ExecuteSkill();
			inputVector = GetInputVector();
			ultCounter = 1;
			StartSkillPrep();
			summonStopwatch.IsRunning = true;
			shatterComplete = false;
			parent.ToggleEnemyFloorCollisions(status: false);
		}

		public override void Update()
		{
			if (currentSS != null && !shatterComplete)
			{
				if (!summonComplete)
				{
					parent.anim.PlayDirectional(animString, -1, animStartTime);
					if (!summonStopwatch.IsRunning)
					{
						summonComplete = true;
						kickStopwatch.IsRunning = true;
					}
				}
				else
				{
					if (CancelToDash())
					{
						return;
					}
					if (!kickDelayComplete)
					{
						if (!kickStopwatch.IsRunning)
						{
							kickDelayComplete = true;
							parent.anim.PlayDirectional(animString, -1, animHoldTime);
							parent.movement.moveVector = inputVector;
							parent.movement.MoveToMoveVector(16f);
						}
						else
						{
							parent.anim.PlayDirectional(animString, -1, animStartTime);
						}
					}
					else
					{
						if (!parent.anim.AnimPlayed(animExecTime))
						{
							return;
						}
						currentSS.Shatter();
						if (isUltimate)
						{
							if (ultCounter < ultShatterCount)
							{
								ultCounter++;
								StartSkillPrep();
								currentSS.riseDelay = kickStopwatch.Delay;
								parent.movement.EndMovement();
								return;
							}
						}
						else
						{
							parent.movement.EndMovement();
						}
						shatterComplete = true;
					}
				}
			}
			else
			{
				ExitToSkillOrRunOrIdle();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleEnemyFloorCollisions();
			if (!shatterComplete && currentSS != null)
			{
				currentSS.BreakStone();
			}
		}

		private void StartSkillPrep()
		{
			spawnPosition = Globals.GetLinecastVector(parent.transform.position, (Vector2)parent.transform.position + inputVector * 2f, ChaosCollisions.layerAll);
			kickDelayComplete = false;
			animString = ((isUltimate && ultShatterCount != ultCounter) ? parent.NextHandAnimStr : parent.KickAnimStr);
			kickStopwatch.SetDelay((!isUltimate || ultCounter <= 0) ? 0.0625f : 0.08f);
			summonComplete = false;
			currentSS = ChaosInst<ShatterStone>(ShatterStone.Prefab, spawnPosition);
			currentSS.attack.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
			currentSS.attack.knockbackOverwriteVector = inputVector;
			if (IsEmpowered)
			{
				currentSS.burstScale = 3.25f;
			}
			if (isUltimate)
			{
				currentSS.burstLevel = ((ultCounter != ultShatterCount) ? 4 : 3);
			}
			else
			{
				currentSS.burstLevel = ((!IsEmpowered) ? 2 : 3);
			}
			PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, spawnPosition);
			SoundManager.PlayWithDistAndSPR("SummonRock", spawnPosition);
		}
	}

