public class ShatterStone : MonoBehaviour
{
	private static GameObject prefab;

	[HideInInspector]
	public Rigidbody2D rigidbody2D;

	public Attack attack;

	public int burstLevel = 2;

	public float burstScale = 2.5f;

	private Vector2 originPosition;

	private Vector2 risePosition;

	private Vector2 shatterPosition;

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(3f);

	private ChaosQuickStopwatch riseStopwatch = new ChaosQuickStopwatch(0f);

	[HideInInspector]
	public float riseDelay = 0.125f;

	private bool riseComplete;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShatterStone.prefab"));

	public void Awake()
	{
		rigidbody2D = GetComponent<Rigidbody2D>();
	}

	public void Start()
	{
		lifeStopwatch.IsRunning = true;
		originPosition = transform.position;
		risePosition = originPosition + Vector2.up;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.5f;
		float startSpeed = 5f;
		Vector3? emitPosition = originPosition;
		poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
		riseStopwatch.SetDelay(riseDelay, stopCurrent: false, autoStart: true);
	}

	public void Update()
	{
		if (!lifeStopwatch.IsRunning)
		{
			BreakStone();
		}
	}

	public void FixedUpdate()
	{
		if (!riseComplete)
		{
			rigidbody2D.MovePosition(Vector2.Lerp(originPosition, risePosition, riseStopwatch.TimePercentage));
			riseComplete = !riseStopwatch.IsRunning;
			if (riseComplete)
			{
				attack.gameObject.SetActive(value: false);
			}
		}
	}

	public void Shatter()
	{
		shatterPosition = transform.position;
		attack.ChangeAttackInfoLevel(burstLevel);
		EarthBurst earthBurst = EarthBurst.CreateBurst(shatterPosition, attack.atkInfo, burstScale);
		earthBurst.attack.knockbackOverwriteVector = attack.knockbackOverwriteVector;
		earthBurst.gameObject.AddComponent<NegateProjectiles>();
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 100;
		Vector3? emitPosition = originPosition;
		poolItem.EmitCircle(particleCount, 1f, -1f, -1f, emitPosition);
		SoundManager.PlayWithDistAndSPR("ShatterStone", shatterPosition);
		CameraController.ShakeCamera();
		BreakStone();
	}

	public void BreakStone()
	{
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(3, transform.position, RockDebrisEmitter.SmallCircleExplosionOverride);
		Object.Destroy(gameObject);
	}
}

