public class UseEarthJump : BaseJumpState
{
	public new static string staticID = "UseEarthJump";

	private static ParticleSystemOverride rockEmitterOverride;

	private bool attackQueued;

	private bool attackFirstFrame;

	private bool fallAnimPlayed;

	private EarthExplosion currentEX;

	private UnstableGround currentUG;

	private int jumpIndex;

	private int maxJumps = 1;

	private bool useUlt;

	private Vector2 currentPosition;

	public UseEarthJump(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		isMeleeSkill = true;
		useSmartCD = true;
		animStartTime = 0.4f;
		animExecTime = 0.3f;
		if (rockEmitterOverride == null)
		{
			rockEmitterOverride = new ParticleSystemOverride
			{
				radius = 1.25f
			};
		}
	}

	private void SetJumpVars()
	{
		jumpHeight = ((!IsEmpowered) ? 3f : 3.5f);
		jumpTime = 0.35f;
		maxJumps = 1;
		jumpBalance = 0.75f;
		landingDelay = 0.15f;
		ref float reference = ref jumpRange;
		float num;
		if (GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false) == Vector2.zero || (parent.inputDevice.IsMouseAim && parent.inputDevice.GetSqMouseDist < 5f))
		{
			num = 0f;
		}
		else
		{
			num = ((jumpIndex <= 0) ? 4.5f : 2.5f);
		}
		reference = num;
		if (isUltimate)
		{
			maxJumps = 3;
			useUlt = true;
		}
		if (jumpIndex > 0)
		{
			disableStartCooldown = true;
			isUltimate = false;
		}
	}

	private void StartJump()
	{
		attackQueued = false;
		attackFirstFrame = true;
		fallAnimPlayed = false;
		parent.anim.PlayDirectional(parent.JumpAnimStr, -1, animStartTime);
		if (jumpIndex <= 0)
		{
			currentPosition = parent.transform.position;
			SoundManager.PlayAudioWithDistance("StandardJump", currentPosition);
			SoundManager.PlayAudioWithDistance("SummonRock", currentPosition);
			PoolManager.GetPoolItem<ParticleEffect>("EarthJumpPlatformEmitter").Emit(1, currentPosition + Vector2.up * 0.5f);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(3, currentPosition + Vector2.up * 0.7f, null, null, 0.75f);
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(2, currentPosition, RockDebrisEmitter.FloorExplosionOverride);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, currentPosition, null, null, 0.75f);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, currentPosition, rockEmitterOverride);
			PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition);
			attackQueued = false;
			attackFirstFrame = true;
			fallAnimPlayed = false;
		}
	}

	public override void OnEnter()
	{
		SetJumpVars();
		base.OnEnter();
		StartJump();
	}

	public override void Update()
	{
		if (!hasLanded)
		{
			if (!fallAnimPlayed && parentThrow.isFalling)
			{
				fallAnimPlayed = true;
				parent.anim.PlayDirectional(parent.FallAnimStr, -1, animStartTime);
			}
			return;
		}
		if (attackQueued)
		{
			if (attackFirstFrame)
			{
				attackFirstFrame = false;
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
				return;
			}
			attackQueued = false;
			CreateEarthExplosion(parent.transform.position);
		}
		if (useUlt && jumpIndex < maxJumps)
		{
			OnEnter();
		}
		else
		{
			base.Update();
		}
	}

	public override void OnExit()
	{
		isUltimate = useUlt;
		base.OnExit();
		jumpIndex = 0;
		useUlt = false;
		disableStartCooldown = false;
	}

	public override void OnLanding()
	{
		base.OnLanding();
		attackQueued = true;
		jumpIndex++;
		parent.airborneStat.RemoveMod(airborneStatMod);
		parent.TogglePreventFallCollider(status: true);
	}

	private void CreateEarthExplosion(Vector3 givenPosition)
	{
		currentEX = ChaosInst<EarthExplosion>(EarthExplosion.Prefab, givenPosition);
		currentEX.attackBox.SetAttackInfo(parent.skillCategory, skillID, 1, useUlt);
		currentEX.attackBox.collider.enabled = true;
		currentEX.warmUpTime = 0f;
		currentEX.waveCount = 0;
		currentEX.spikeCount = 0;
		currentEX.spawnRange = 1.75f;
		currentEX.attackRadius = 2.5f;
		currentEX.emitCountOverride = 4;
		currentEX.emitRadiusOverride = 1.75f;
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, givenPosition);
		SoundManager.PlayWithDistAndSPR("GroundSlam", givenPosition);
		if (IsEmpowered)
		{
			currentUG = ChaosInst<UnstableGround>(UnstableGround.Prefab, givenPosition);
			currentUG.attack.SetAttackInfo(parent.skillCategory, skillID, 2, useUlt);
			currentUG.hitImmediate = false;
			currentUG.hitCount = 4;
		}
	}
}

public class UseEarthRebound : BaseJumpState
{
	public new static string staticID = "UseEarthRebound";

	private int maxComboCount = 3;

	private int comboCounter;

	private bool atkPrimed;

	private bool targetHit;

	private bool jumpStarted;

	private EarthRebound currentER;

	private List<EarthRebound> erList = new List<EarthRebound>();

	private ChaosQuickStopwatch attackStopwatch = new ChaosQuickStopwatch(0.0625f);

	public override string OnEnterAnimStr => parent.ForehandAnimStr;

	public UseEarthRebound(FSM parentFSM, Player parentEnt)
		: base(staticID, parentFSM, parentEnt)
	{
		isMeleeSkill = true;
		startCooldownOnEnter = false;
		useSmartCD = true;
		SetAnimTimes(0.15f, 0.2f, 0.3f, 0.5f);
		useCalcValues = false;
		jumpTime = 0.3f;
		jumpHeight = 1.25f;
		jumpBalance = 0.5f;
		jumpRange = 4f;
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		maxComboCount = ((!IsEmpowered) ? 3 : 4);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		inputVector = parent.GetInputVector();
		parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
		holdStarted = false;
		holdReleased = false;
		skillExecuted = false;
		comboCounter = 0;
		atkPrimed = false;
		targetHit = false;
		jumpStarted = false;
		erList.Clear();
	}

	public override void Update()
	{
		if (jumpStarted)
		{
			base.Update();
		}
		else if (skillExecuted)
		{
			ConcludeSkill();
		}
		else if (parent.anim.AnimPlayed(animExecTime))
		{
			ExecuteSkill();
		}
	}

	public override void ExecuteSkill()
	{
		if (!atkPrimed)
		{
			atkPrimed = true;
			comboCounter++;
			CreateEarthRebound();
			parent.movement.moveVector = inputVector;
			if (comboCounter == 1 || comboCounter >= maxComboCount)
			{
				StartCooldownTimer();
				attackStopwatch.SetDelay(0.1f, stopCurrent: false, autoStart: true);
				parent.movement.MoveToMoveVector(35f);
			}
			else
			{
				attackStopwatch.SetDelay(0.0625f, stopCurrent: false, autoStart: true);
				parent.movement.MoveToMoveVector(28f);
			}
		}
		if (CancelToDash(enableButtonHeld: true) || attackStopwatch.IsRunning)
		{
			return;
		}
		parent.movement.EndMovement();
		if (comboCounter < maxComboCount)
		{
			atkPrimed = false;
		}
		if (!atkPrimed)
		{
			parent.anim.PlayDirectional((comboCounter >= maxComboCount - 1) ? parent.KickAnimStr : parent.NextHandAnimStr, -1, 0.25f);
			return;
		}
		if (targetHit)
		{
			InitJump();
		}
		base.ExecuteSkill();
	}

	public override void OnLanding()
	{
		if (!targetHit || hasLanded || fsm.nextStateName.Contains("Hurt") || fsm.nextStateName.Contains("Dead"))
		{
			return;
		}
		base.OnLanding();
		parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, 0.3f);
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, parent.transform.position);
		SoundManager.PlayWithDistAndSPR("GroundSlam", parent.transform.position);
		parent.movement.moveVector = -inputVector;
		parent.movement.MoveToMoveVector();
		for (int num = erList.Count - 1; num >= 0; num--)
		{
			if (!(erList[num] == null))
			{
				Attack attack = erList[num].attack;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
				erList[num].Detonate();
			}
		}
		erList.Clear();
	}

	public override void OnExit()
	{
		base.OnExit();
		for (int num = erList.Count - 1; num >= 0; num--)
		{
			if (!(erList[num] == null))
			{
				Attack attack = erList[num].attack;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
				erList[num].Crumble();
			}
		}
		erList.Clear();
	}

	private void CreateEarthRebound()
	{
