	private void Start()
	{
		warmUpStopwatchID = ChaosStopwatch.Begin(warmUpTime);
		attackStopwatchID = ChaosStopwatch.Begin(warmUpTime + attackActiveTime);
		Object.Destroy(gameObject, warmUpTime + attackActiveTime + destroyTime);
		if (showCastingCircle)
		{
			castingCircle = CastingCirclePool.Spawn("Draw", transform.position, parentObj: gameObject, unitSizeY: attackRadius, color: CastingCircle.enemyColor, drawTime: warmUpTime * 0.75f, disableWithParentVal: true, trackParentVal: true, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: attackRadius);
		}
