			{
				explosionEmitter.Emit((int)(20f * attackRadius / 1.5f), transform.position, new ParticleSystemOverride
				{
					radius = ((emitRadiusOverride != -1f) ? emitRadiusOverride : attackRadius)
				});
			}
			if (castingCircle != null)
			{
				castingCircle.Reset();
			}
			attackCol.enabled = true;
			CameraController.ShakeCamera();
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = ((dustEmitCountOverride != -1) ? dustEmitCountOverride : 200);
			Vector3? emitPosition = transform.position;
			float startSize = ((dustEmitStartSizeOverride != 0f) ? dustEmitStartSizeOverride : 1.5f);
			poolItem.EmitCircle(particleCount, 1f, -1f, startSize, emitPosition);
			shadowSprite.enabled = false;
		}
		if (ChaosStopwatch.Check(attackStopwatchID))
		{
			attackCol.enabled = false;
		}
	}

	private void OnDestroy()
	{
		if (castingCircle != null)
		{
			castingCircle.Reset();
		}
	}

	private void LateUpdate()
	{
		if (!exploded && followTransform != null)
		{
			transform.position = followTransform.position;
		}
	}

	private void CreateRing(bool isFirst, int currentWaveCount)
	{
		int num = 3;
		int num2 = num * spikeCount;
		for (int i = Random.Range(0, num); i < num2; i += num)
		{
			Vector3 vector = transform.position + (Vector3)Globals.GetCirclePositionVector(num2, i) * (spawnRange + (float)currentWaveCount);
		}
		SoundManager.PlayAudioWithDistance("EarthExplosion", transform.position);
	}
}
