	private SpriteRenderer spriteRenderer;

	private ParticleSystem earthPartSys;

	[HideInInspector]
	public Attack attack;

	[HideInInspector]
	public bool targetHit;

	public Transform followTrans;

	public Vector3 followOffset;

	private Vector3 followStart = Vector3.zero;

	public ChaosQuickStopwatch lerpStopwatch = new ChaosQuickStopwatch();

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(2.5f);

	private bool destroyQueued;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/EarthRebound.prefab"));

	private void Awake()
	{
		this.attack = transform.Find("Attack").GetComponent<Attack>();
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		spriteRenderer = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		earthPartSys = transform.Find("EarthPartSys").GetComponent<ParticleSystem>();
	}

	private void Start()
	{
		lifeStopwatch.IsRunning = true;
		string audioID = "EarthDust";
		Vector2? soundOrigin = transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.125f, standardPitchRange);
	}

	private void LateUpdate()
	{
		if (!destroyQueued)
		{
			if (followTrans == null)
			{
				Crumble();
			}
			else
			{
				transform.position = followTrans.position + Vector3.Lerp(followStart, followOffset, lerpStopwatch.TimePercentage);
			}
			if (!lifeStopwatch.IsRunning || (!targetHit && !lerpStopwatch.IsRunning))
			{
				Crumble();
			}
		}
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (!targetHit && !(givenEntity == null))
		{
			targetHit = true;
			lerpStopwatch.IsRunning = false;
			followTrans = givenEntity.hurtBoxTransform;
			followOffset = UnityEngine.Random.insideUnitCircle * 0.35f;
			attack.gameObject.SetActive(value: false);
		}
	}

	public void Detonate()
	{
		if (!destroyQueued)
		{
			if (followTrans != null)
			{
				EarthBurst.CreateBurst(followTrans.position - (Vector3)attack.knockbackOverwriteVector * 0.125f, attack.ChangeAttackInfoLevel(2), 2.5f);
			}
			string audioID = "EarthExplosionShort";
			Vector2? soundOrigin = transform.position;
			float overridePitch = UnityEngine.Random.Range(0.85f, 0.95f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			Crumble();
		}
	}

	public void Crumble()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			if (attack != null)
			{
				attack.gameObject.SetActive(value: false);
			}
			if (spriteRenderer != null)
			{
				spriteRenderer.enabled = false;
			}
			if (earthPartSys != null)
			{
				earthPartSys.Emit(10);
				earthPartSys.Stop();
			}
			string audioID = "EarthPebble";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			UnityEngine.Object.Destroy(gameObject, 0.5f);
		}
	}
}
