using UnityEngine;

public class UnstableGround : MonoBehaviour
{
	private static GameObject prefab;

	public Attack attack;

	public CircleCollider2D attackCol;

	public ParticleSystem dustPartSys;

	public float attackRadius = 3f;

	private int hitStopwatchID;

	public int hitCount = 5;

	public float hitInterval = 0.25f;

	public bool hitImmediate = true;

	private bool hitCompleted;

	private Vector2[] riftArray = new Vector2[6];

	private SectionedTrailEmitter stEmitter;

	private bool priCheck;

	private bool secCheck;

	private Vector2 priVec;

	private Vector2 secVec;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/UnstableGround.prefab"));

	private void Start()
	{
		attackCol.radius = attackRadius;
		if (!hitImmediate)
		{
			hitCount++;
		}
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitInterval, hitCount);
		for (int i = 0; i < 6; i++)
		{
			ref Vector2 reference = ref riftArray[i];
			reference = (Vector2)transform.position + Globals.GetCirclePositionVector(12, i * 2 + 1) * (attackRadius + 0.5f);
		}
	}

	private void FixedUpdate()
	{
		if (hitCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Running:
			attackCol.enabled = false;
			break;
		case StopwatchState.Ready:
			CreateEffects(transform.position);
			if (hitImmediate)
			{
				attackCol.enabled = true;
			}
			else
			{
				hitImmediate = true;
			}
			break;
		case StopwatchState.Done:
			hitCompleted = true;
			attackCol.enabled = false;
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 0.25f);
			}
			break;
		}
	}

	private void CreateEffects(Vector2 givenPosition)
	{
		dustPartSys.Emit(Random.Range(10, 15));
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, givenPosition);
		string audioID = "GroundSlam";
		Vector2? soundOrigin = givenPosition;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		stEmitter = PoolManager.GetPoolItem<SectionedTrailEmitter>("FloorRift");
		for (int i = 0; i < 6; i++)
		{
			priVec = riftArray[i];
			secVec = riftArray[(i + 1) % 6];
			priCheck = Globals.CheckCircle(priVec, 0.25f, ChaosCollisions.layerAll);
			secCheck = Globals.CheckCircle(secVec, 0.25f, ChaosCollisions.layerAll);
			if (priCheck)
			{
				if (secCheck)
				{
					stEmitter.Emit(riftArray[i], riftArray[(i + 1) % 6]);
				}
				else
				{
					stEmitter.Emit(priVec, Globals.GetLinecastVector(priVec, secVec, ChaosCollisions.layerAll));
				}
			}
			else if (secCheck)
			{
				stEmitter.Emit(secVec, Globals.GetLinecastVector(secVec, priVec, ChaosCollisions.layerAll));
			}
		}
	}
}

	public class UseChessPiece : SkillState
	{
		private struct ChessPieceVars
		{
			public Vector2 spawnVector;

			public Vector2 endVector;

			public bool startRight;

			public bool endRight;

			public bool changeColor;
		}

		public new static string staticID = "StalwartDefenders";

		private static Vector2[] moveVectors = new Vector2[4]
		{
			new Vector2(-1.5f, 3f),
			new Vector2(-3f, 1.5f),
			new Vector2(3f, 1.5f),
			new Vector2(1.5f, 3f)
		};

		private static float movementUnit = 1.5f;

		private static float[] delayTimes = new float[4] { 0.1875f, 0.0625f, 0.25f, 0.125f };

		private static Color altColor = new Color(0.5f, 0.5f, 0.5f, 1f);

		private ChessPiece currentCP;

		private Vector2 spawnCenter;

		private Vector2 perpendVec;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public UseChessPiece(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			SetAnimTimes(0.1f, 0.2f, 0.3f, 0.8f, 0.9f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			inputVector = Entity.GetFacingDirectionVector(parent.facingDirection);
			spawnCenter = Globals.GetSafeLinecastVector(parent.transform.position, inputVector, movementUnit, ChaosCollisions.layerAllWallAndObst);
			perpendVec = Globals.GetPerpendicular(inputVector) * movementUnit;
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			spawnCenter -= perpendVec * 1.5f;
			for (int i = 0; i < 4; i++)
			{
				CreateChessPiece(GetChessVars(parent.facingDirection, i), delayTimes[i]);
			}
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 100;
			float scale = 0.25f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			SoundManager.PlayAudioWithDistance("ChessPiece", spawnCenter);
			SoundManager.PlayAudioWithDistance("RockForm", spawnCenter);
		}

		private void CreateChessPiece(ChessPieceVars givenVars, float givenDelay)
		{
			if (Globals.CheckCircle(givenVars.spawnVector, 0.125f, ChaosCollisions.layerAll))
			{
				currentCP = ChaosInst<ChessPiece>(ChessPiece.Prefab, givenVars.spawnVector);
				currentCP.landingPosition = givenVars.endVector;
				currentCP.skillCategory = parent.skillCategory;
				currentCP.attack.SetAttackInfo(parent.skillCategory, skillID);
				currentCP.attack.knockbackOverwriteVector = inputVector;
				currentCP.startRight = givenVars.startRight;
				currentCP.endRight = givenVars.endRight;
				currentCP.spawnDelay = givenDelay;
				if (givenVars.changeColor)
				{
					currentCP.spriteRenderer.color = altColor;
				}
				currentCP.isEmpowered = IsEmpowered;
			}
		}

		private ChessPieceVars GetChessVars(FacingDirection givenDir, int givenIndex)
		{
			ChessPieceVars result = new ChessPieceVars
			{
				spawnVector = spawnCenter + perpendVec * givenIndex,
				endVector = Vector2.zero
			};
			switch (givenDir)
			{
			case FacingDirection.Up:
				result.endVector = moveVectors[givenIndex];
				result.startRight = givenIndex < 2;
				result.endRight = !result.startRight;
				break;
			case FacingDirection.Down:
				result.endVector = -moveVectors[givenIndex];
				result.startRight = givenIndex >= 2;
				result.endRight = !result.startRight;
				break;
			case FacingDirection.Left:
				result.endVector = Globals.GetPerpendicular(moveVectors[givenIndex]);
				result.startRight = false;
				result.endRight = false;
				break;
			case FacingDirection.Right:
				result.endVector = Globals.GetPerpendicular(moveVectors[givenIndex], horizontal: false);
				result.startRight = true;
				result.endRight = true;
				break;
			}
			result.changeColor = givenIndex < 2;
			result.endVector += result.spawnVector;
			return result;
		}
	}

using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class ChessPiece : Entity
{
	public class SpawnState : State<ChessPiece>
	{
		private int delayStopwatchID;

		private bool animPlayed;

		private bool firstFrame;

		public SpawnState(string newName, FSM newFSM, ChessPiece newEnt)
			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			parent.anim.Play("Spawn", -1, 0f);
			animPlayed = false;
			firstFrame = true;
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(parent.debrisType, 15, parent.transform.position, RockDebrisEmitter.SmallCircleExplosionOverride);
			CameraController.ShakeCamera(1f, ignoreShakeCount: true);
		}

		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (animPlayed)
			{
				if (ChaosStopwatch.Check(delayStopwatchID))
				{
					fsm.ChangeState("Jump");
				}
			}
			else if (parent.anim.AnimPlayed())
			{
				animPlayed = true;
				delayStopwatchID = ChaosStopwatch.Begin(parent.spawnDelay);
				parent.ToggleLayers(status: false);
			}
		}
	}

	public class JumpState : State<ChessPiece>
	{
		private bool landed;

		private bool landingIsSafe;

		private int delayStopwatchID = -1;

		public JumpState(string newName, FSM newFSM, ChessPiece newEnt)
			: base(newName, newFSM, newEnt)
		{
			ThrownItem thrownItem = parent.thrownItem;
			thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(HandleLandingEvent));
		}

		public override void OnEnter()
		{
			parent.ToggleColliders(status: false);
			parent.anim.Play("Idle", -1, 0f);
			parent.attack.ChangeAttackInfoLevel(2);
			parent.thrownItem.ThrowToTargetVector(parent.landingPosition);
			string audioID = "StandardJump";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			landingIsSafe = Globals.CheckCircle(parent.landingPosition, 0.125f, ChaosCollisions.layerPit);
			parent.facingDirection = (parent.endRight ? FacingDirection.Right : FacingDirection.Left);
			landed = false;
		}

		public override void Update()
		{
			if (landed && ChaosStopwatch.Check(delayStopwatchID))
			{
				fsm.ChangeState("Idle");
			}
		}

		public override void OnExit()
		{
			parent.attack.collider.enabled = false;
		}

		public void HandleLandingEvent()
		{
			landed = true;
			parent.rigidbody2D.velocity = Vector3.zero;
			parent.rigidbody2D.isKinematic = true;
			parent.ToggleColliders(status: true);
			parent.ToggleLayers(status: true);
			if (!landingIsSafe)
			{
				parent.destroyDelay = 0f;
				return;
			}
			CameraController.ShakeCamera(1f, ignoreShakeCount: true);
			delayStopwatchID = ChaosStopwatch.Begin(parent.jumpDelay);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 40;
			float scale = 0.25f;
			Vector3? emitPosition = parent.transform.position + Vector3.down * 0.25f;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			string audioID = "RockExplode";
			Vector2? soundOrigin = parent.transform.position;
			scale = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
			if (parent.empoweredJump)
			{
				EarthBurst.CreateBurst(parent.transform.position, parent.skillCategory, parent.attack.atkInfo.skillID, 3).skipParticleEmit = true;
				PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(parent.debrisType, 10, parent.transform.position, RockDebrisEmitter.FloorExplosionOverride);
				PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(parent.debrisType, 5, parent.transform.position, RockDebrisEmitter.FloorExplosionOverride);
				if (parent.gameObject != null)
				{
					UnityEngine.Object.Destroy(parent.gameObject);
				}
			}
		}
	}

	public class IdleState : State<ChessPiece>
	{
		private new ChessPiece parent;

		private int delayStopwatchID = -1;

		public IdleState(string stateName, FSM parentFSM, ChessPiece parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			parent = parentEntity;
		}

		public override void OnEnter()
		{
			GameController.allies.Add(parent.gameObject);
			if (parent.isEmpowered)
			{
				parent.empoweredJump = !parent.empoweredJump;
				if (parent.empoweredJump)
				{
					parent.landingPosition = parent.transform.position;
					parent.thrownItem.throwHeight *= 0.75f;
					delayStopwatchID = ChaosStopwatch.Begin(parent.destroyDelay * 0.5f);
				}
			}
			else
			{
				delayStopwatchID = ChaosStopwatch.Begin(parent.destroyDelay);
			}
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				if (parent.empoweredJump)
				{
					fsm.ChangeState("Jump");
				}
				else if (parent.gameObject != null)
				{
					string audioID = "RockExplode";
