	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/BoulderShield.prefab"));

	private void Awake()
	{
		anim = GetComponent<Animator>();
		health = GetComponent<Health>();
		movement = GetComponent<Movement>();
		spriteRenderer = transform.Find("BoulderSprite").GetComponent<SpriteRenderer>();
		attack = transform.Find("AttackBox").GetComponent<Attack>();
		negateProjectiles = transform.Find("NegateProjectiles").GetComponent<NegateProjectiles>();
		hurtBoxCollider = transform.Find("AllyHurtBox").GetComponent<Collider2D>();
		spriteSorter = spriteRenderer.GetComponent<SortSpriteLayer>();
	}

	private void Start()
	{
		anim.speed = UnityEngine.Random.Range(0.9f, 1.1f);
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnAttack));
		Attack attack2 = this.attack;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnAttack));
		audioStopwatchID = ChaosStopwatch.Begin(UnityEngine.Random.Range(0f, maxOrbitTime * 0.8f));
		if (!disableOrbit)
		{
			orbitStopwatchID = ChaosStopwatch.Begin(maxOrbitTime);
			movement.InitOrbitAngle(spawnAngle);
			movement.orbit = true;
			movement.orbitSpeed = initOrbitSpeed;
			initOrbitRadius = movement.orbitRadius;
			extOrbitRadius = initOrbitRadius + 0.5f;
		}
		GameController.allies.Add(gameObject);
	}

	private void Update()
	{
		if (!destroyQueued)
		{
			if ((!disableOrbit && ChaosStopwatch.Check(orbitStopwatchID)) || (float)health.CurrentHealthValue <= 0f)
			{
				Reset();
			}
			else if (!audioPlayed && ChaosStopwatch.Check(audioStopwatchID))
			{
				audioPlayed = true;
				string audioID = "EarthDust";
				Vector2? soundOrigin = transform.position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
				PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(5, transform.position);
			}
		}
	}

	private void FixedUpdate()
	{
		if (parentTrans != null && !disableOrbit)
		{
			orbitSpeedLerpValue = ChaosStopwatch.GetTimePercentage(orbitStopwatchID);
			if (orbitSpeedLerpValue > 0.8f)
			{
				movement.orbitSpeed = Mathf.Lerp(initOrbitSpeed, minOrbitSpeed, orbitSpeedLerpValue);
			}
			movement.OrbitTarget(parentTrans.position);
			knockbackVector = movement.orbitVector;
			attack.knockbackOverwriteVector = knockbackVector;
			UpdateShieldSprite(knockbackVector);
		}
	}

	public void UpdateShieldSprite(Vector2 givenVector, bool autoFlipX = true, bool forcePositiveX = false, bool useLargeSprite = false)
	{
		if (forcePositiveX && givenVector.x < 0f)
		{
			givenVector = new Vector2(givenVector.x * -1f, givenVector.y);
		}
		calcSpriteIndex = Mathf.Clamp((int)((195f - Vector2.Angle(Vector2.up, givenVector)) * 0.033f), 0, 6);
		if (curSpriteIndex == calcSpriteIndex && !useLargeSprite)
		{
			return;
		}
		curSpriteIndex = calcSpriteIndex;
		if (useLargeSprite)
		{
			if (autoFlipX && givenVector.x < 0f && curSpriteIndex != 0 && curSpriteIndex != 6)
			{
				spriteRenderer.transform.localScale = new Vector3(-1f, spriteRenderer.transform.localScale.y, spriteRenderer.transform.localScale.z);
			}
			UpdateShieldSpriteLarge();
			return;
		}
		if (autoFlipX && givenVector.x < 0f && curSpriteIndex != 0 && curSpriteIndex != 6)
		{
			curSpriteIndex = 12 - curSpriteIndex;
		}
		spriteRenderer.sprite = spriteVars[curSpriteIndex];
		curSpriteIndex = curSpriteIndex;
	}

	public void UpdateShieldSpriteLarge()
	{
		if (curSpriteIndex == 0)
		{
			spriteRenderer.sprite = spriteVars[12];
		}
		else if (curSpriteIndex == 1 || curSpriteIndex == 2)
		{
			spriteRenderer.sprite = spriteVars[13];
		}
		else if (curSpriteIndex == 3)
		{
			spriteRenderer.sprite = spriteVars[14];
		}
		else if (curSpriteIndex == 4 || curSpriteIndex == 5)
		{
			spriteRenderer.sprite = spriteVars[15];
		}
		else if (curSpriteIndex == 6)
		{
			spriteRenderer.sprite = spriteVars[16];
		}
	}

	private void OnAttack(Collider2D col)
	{
		StartCoroutine(health.FlashRed());
		StartCoroutine(BashAnim());
	}
	public class BaseWardState : SkillState
	{
		public GameObject wardPrefab;

		public Ward currentWard;

		private static float spawnRange = 3f;

		private static int maxSpawnCount = 6;

		private float duration = 1f;

		private int spawnCount = 1;

		private int healthValue = 1;

		private Vector2 currentPosition;

		private int maxPosCount;

		private int calcPosCount;

		private int offsetCount;

		private bool skipEvens;

		public override string OnEnterAnimStr => parent.GSlamAnimStr;

		public BaseWardState(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			isBuffSkill = true;
			isSummonSkill = true;
			SetAnimTimes(0.25f, 0.2f, 0.3f, 0.35f, 0.4f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			ApplyStopElement();
			CameraController.ShakeCamera(0.25f);
			duration = skillData.GetValue<float>(StatData.durStr);
			spawnCount = Mathf.Min(maxSpawnCount, skillData.GetValue<int>(StatData.spawnStr));
			healthValue = skillData.GetValue<int>(StatData.healthStr);
			maxPosCount = maxSpawnCount;
			calcPosCount = spawnCount;
			skipEvens = calcPosCount % 2 == 0;
			if (skipEvens)
			{
				calcPosCount *= 2;
				maxPosCount *= 2;
			}
			offsetCount = (int)((float)calcPosCount * 0.5f);
			currentPosition = parent.transform.position;
			for (int i = -offsetCount; i <= offsetCount; i++)
			{
				if (!skipEvens || i % 2 != 0)
				{
					CreateWard(Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetRotatedCircleVector(maxPosCount, i, inputVector) * spawnRange, ChaosCollisions.layerAllWallAndObst));
				}
			}
		}

		public virtual void CreateWard(Vector2 givenPosition)
		{
			currentWard = ChaosInst<Ward>(wardPrefab, givenPosition);
			currentWard.duration = duration;
			currentWard.startingHealth = healthValue;
			currentWard.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentWard.isEmpowered = IsEmpowered;
			currentWard.gameObject.name = wardPrefab.name + parent.skillCategory;
			parent.playerSummonsList.Add(currentWard.gameObject);
		}
	}

