	private IEnumerator BashAnim()
	{
		movement.orbitRadius = extOrbitRadius;
		bashStopwatch.IsRunning = true;
		while (!destroyQueued && bashStopwatch.IsRunning)
		{
			movement.orbitRadius = Mathf.Lerp(extOrbitRadius, initOrbitRadius, bashStopwatch.TimePercentage);
			yield return null;
		}
		movement.orbitRadius = initOrbitRadius;
	}

	private IEnumerator EndShield()
	{
		Attack attack = this.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnAttack));
		movement.orbit = false;
		if (destroyDelay > 0f)
		{
			yield return new WaitForSeconds(destroyDelay);
		}
		if (playFXOnDestroy)
		{
			SoundManager.PlayAudioWithDistance("EarthPebble", transform.position);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, transform.position);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(1, transform.position, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
		}
		if (gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
	}
