					}
					else
					{
						base.ExecuteSkill();
						StartCooldownTimer();
					}
					return;
				}
				CancelToDash();
			}
			else
			{
				base.ExecuteSkill();
				CreateSpikeRing();
				StartCooldownTimer();
			}
