public class SpikeRing : Wave
{
	private ParticleSystemOverride pSysOverride = new ParticleSystemOverride
	{
		startLifetime = 0.4f
	};

	private static GameObject ringPrefab;

	public float initRingRadius = 1.5f;

	public float ringRadiusIncrement = 0.625f;

	public int initSpawnCount = 7;

	public bool offsetSpawn;

	public bool useFloorCrack = true;

	private float currentRadius;

	private CircleCollider2D waveCollider;

	public bool isEmpowered;

	public bool addWavesElapsed = true;

	public static GameObject Prefab => ringPrefab ?? (ringPrefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/SpikeRing.prefab"));

	public override void Start()
	{
		stopLayerMask = 0;
		if (isEmpowered)
		{
			for (wavesElapsed = 0; wavesElapsed < maxWaveCount - 1; wavesElapsed++)
			{
				currentRadius = initRingRadius + ringRadiusIncrement * (float)wavesElapsed;
				CreateSpikeRing();
			}
			maxWaveCount = 1;
			wavePoolSize = 1;
		}
		base.Start();
		SoundManager.PlayWithDistAndSPR("GroundSlam", transform.position);
		if (useFloorCrack)
		{
			PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position);
		}
	}

	public override GameObject CreateWaveCollisionDetector(Transform parentTrans)
	{
		GameObject gameObject = new GameObject("WaveCollisionDetector");
		gameObject.transform.SetParent(parentTrans);
		gameObject.transform.localPosition = Vector3.zero;
		WaveCollisionDetector waveCollisionDetector = gameObject.AddComponent<WaveCollisionDetector>();
		waveCollisionDetector.waveCollisionEventHandler = (WaveCollisionDetector.WaveCollisionEventHandler)Delegate.Combine(waveCollisionDetector.waveCollisionEventHandler, new WaveCollisionDetector.WaveCollisionEventHandler(OnWaveCollision));
		waveCollider = gameObject.AddComponent<CircleCollider2D>();
		waveCollider.isTrigger = true;
		waveCollider.enabled = false;
		return gameObject;
	}

	public override void ActivateWave()
	{
		if (wavePoolAttacks[waveCount].collider != null)
		{
			wavePoolAttacks[waveCount].collider.enabled = false;
		}
		currentRadius = initRingRadius + ringRadiusIncrement * (float)wavesElapsed;
		CreateSpikeRing();
		base.ActivateWave();
		currentRadius += 0.5f;
		if (wavePoolAttacks[waveCount].collider != null)
		{
			((CircleCollider2D)wavePoolAttacks[waveCount].collider).radius = currentRadius;
		}
		waveCollider.radius = currentRadius;
		waveCollider.enabled = true;
		CameraController.ShakeCamera(0.5f);
		UnityEngine.Object.Destroy(wavePoolTrans[waveCount].gameObject, 0.2f);
	}

	private void CreateSpikeRing()
	{
		int num = initSpawnCount * 2;
		if (addWavesElapsed)
		{
			num += wavesElapsed * 2;
		}
		else
		{
			offsetSpawn = !offsetSpawn;
		}
		for (int i = (offsetSpawn ? 1 : 0); i < num; i += 2)
		{
			Vector3 vector = (Vector3)Globals.GetCirclePositionVector(num, i) * currentRadius + transform.position;
			if (Globals.CheckCircle(vector, 0.25f, ChaosCollisions.layerAll))
			{
				PoolManager.GetPoolItem<ParticleEffect>("EarthWaveEffect").Emit(1, vector, (!useFloorCrack) ? pSysOverride : null);
				if (useFloorCrack)
				{
					PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, vector);
				}
			}
		}
	}
