using System;
using System.Collections.Generic;
using UnityEngine;

public class GraspingEarth : MonoBehaviour
{
	private static GameObject prefab;

	private static Dictionary<int, GraspingEarth> entityHitDict = new Dictionary<int, GraspingEarth>();

	private int entityInstID;

	private Animator anim;

	private Health health;

	[HideInInspector]
	public Attack attack;

	[HideInInspector]
	public Entity targetEntity;

	private Health targetHealth;

	private AttackInfo rootAtkInfo;

	private AttackInfo baseAtkInfo;

	private AttackInfo firstAtkInfo;

	private AttackInfo finalAtkInfo;

	private Transform targetTrans;

	private bool durationComplete;

	private bool firstHit = true;

	private int dmgStopwatchID;

	private float dmgInteval = 0.5f;

	private int intervalCount = 5;

	private bool finalHitApplied;

	private bool isInstantFinal;

	private string skillModID;

	public bool isEmpowered;

	private FloorCrackEffect floorCrack;

	private static Vector3 _spawnOffset;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/GraspingEarth.prefab"));

	public static Vector3 SpawnOffset
	{
		get
		{
			if (_spawnOffset == Vector3.zero)
			{
				_spawnOffset = new Vector3(0f, -0.25f, 0f);
			}
			return _spawnOffset;
		}
	}

	private void Awake()
	{
		anim = GetComponent<Animator>();
		attack = GetComponent<Attack>();
		health = GetComponent<Health>();
	}

	private void Start()
	{
		if (isEmpowered)
		{
			dmgInteval *= 0.75f;
			intervalCount *= 2;
		}
		intervalCount++;
		this.health.entitySprites.Add(transform.Find("SpriteBG").GetComponent<SpriteRenderer>());
		if (targetEntity == null || targetEntity.health == null)
		{
			Reset();
			return;
		}
		entityInstID = targetEntity.GetInstanceID();
		if (entityHitDict.ContainsKey(entityInstID) && entityHitDict[entityInstID] != null)
		{
			entityHitDict[entityInstID].Reset();
		}
		entityHitDict[entityInstID] = this;
		targetTrans = targetEntity.transform;
		targetHealth = targetEntity.health;
		skillModID = attack.atkInfo.skillID + gameObject.GetInstanceID();
		rootAtkInfo = attack.ChangeAttackInfoLevel(1);
		baseAtkInfo = attack.ChangeAttackInfoLevel(2);
		firstAtkInfo = attack.ChangeAttackInfoLevel(3);
		finalAtkInfo = attack.ChangeAttackInfoLevel(4);
		if (!CheckTargetState())
		{
			isInstantFinal = true;
			finalAtkInfo.damage = Mathf.CeilToInt((float)finalAtkInfo.damage * ((!isEmpowered) ? 2f : 2.4f));
			dmgStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, dmgInteval, 1);
		}
		else
		{
			ApplyAtkInfo(rootAtkInfo);
		}
		anim.Play("Grab", -1, 0f);
		PlaySpawnEffects();
		Health health = targetHealth;
		health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(TargetTookDamage));
		Health health2 = targetHealth;
		health2.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health2.takeDamageEventHandlers, new Health.OnTakeDamageHandler(TargetTookDamage));
	}

	private void PlaySpawnEffects()
	{
		floorCrack = PoolManager.GetPoolItem<FloorCrackEffect>();
		floorCrack.Crack(transform.position - SpawnOffset, 0f, 5f);
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(10, transform.position);
		PoolManager.GetPoolItem<DustEmitter>().EmitCircle(50, 1f, 6f, -1f, transform.position);
	}

	private void ApplyAtkInfo(AttackInfo givenAtkInfo)
	{
		if (!(targetEntity == null) && !(targetHealth == null))
		{
			targetEntity.ignorePrevHitStunDuration = true;
			Entity givenEntity = targetEntity;
			bool status = false;
			string modID = skillModID;
			RootDotEffect.ToggleMovementMods(givenEntity, status, setMovement: true, setKnockback: true, modID);
			targetHealth.TakeDamage(givenAtkInfo);
			givenEntity = targetEntity;
			status = true;
			modID = skillModID;
			RootDotEffect.ToggleMovementMods(givenEntity, status, setMovement: true, setKnockback: true, modID);
		}
	}

	private void Update()
	{
		if (durationComplete)
		{
			return;
		}
		if (CheckTargetState())
		{
			if (firstHit)
			{
				return;
			}
			switch (ChaosStopwatch.CheckInterval(dmgStopwatchID))
			{
			case StopwatchState.Ready:
				if (ChaosStopwatch.IntervalIsActive(dmgStopwatchID))
				{
					anim.Play("Attack", -1, 0f);
					ApplyAtkInfo(baseAtkInfo);
				}
				else
				{
					finalHitApplied = true;
					ApplyAtkInfo(finalAtkInfo);
				}
				break;
			case StopwatchState.Done:
				Reset();
				break;
			}
			if (health.CurrentHealthValue <= 0)
			{
				Reset();
			}
		}
		else
		{
			Reset();
		}
	}

	private void LateUpdate()
	{
		if (targetTrans != null)
		{
			targetTrans.position = transform.position - SpawnOffset;
		}
	}

	private void TargetTookDamage(AttackInfo givenAtkInfo, Entity givenEntity = null)
	{
		if (targetEntity != null && targetEntity.movement != null)
		{
			targetEntity.movement.EndMovement();
		}
		health.TakeDamage(givenAtkInfo);
		PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect").EmitSingle(RockDebrisType.Default, 3, transform.position + Vector3.up, null, null, 0f, -2f);
		if (givenAtkInfo.shakeCamera)
		{
			CameraController.ShakeCamera(Mathf.Min((float)givenAtkInfo.damage * 0.02f, 2f));
		}
	}

	private bool CheckTargetState()
	{
		return targetEntity != null && targetHealth.CurrentHealthValue > 0 && !targetHealth.ignoreGrab;
	}

	private void Reset()
	{
		firstHit = true;
		durationComplete = true;
		Entity givenEntity = targetEntity;
		bool status = false;
		string modID = skillModID;
		RootDotEffect.ToggleMovementMods(givenEntity, status, setMovement: true, setKnockback: true, modID);
		targetTrans = null;
		entityHitDict.Remove(entityInstID);
		if (targetEntity != null && !finalHitApplied)
		{
			finalHitApplied = true;
			targetEntity.ignorePrevHitStunDuration = true;
			targetHealth.TakeDamage(finalAtkInfo);
			targetEntity = null;
			if (isInstantFinal)
			{
				EarthBurst.CreateBurst(transform.position + Vector3.up, string.Empty, string.Empty, 1, 3f);
			}
		}
		anim.Play("Break", -1, 0f);
		SoundManager.PlayWithDistAndSPR("GroundSlam", transform.position);
		UnityEngine.Object.Destroy(gameObject, 1f);
	}

	private void OnDestroy()
	{
		if (targetEntity != null && entityHitDict.ContainsKey(entityInstID) && entityHitDict[entityInstID] == this)
		{
			entityHitDict.Remove(entityInstID);
		}
		if (targetHealth != null)
		{
			Health health = targetHealth;
			health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(TargetTookDamage));
		}
	}

	public void ApplyFirstHit()
	{
		ApplyAtkInfo(firstAtkInfo);
		if (GameController.pvpOn && targetEntity is Player)
		{
			intervalCount = 2;
		}
		dmgStopwatchID = ChaosStopwatch.Begin(dmgInteval, useInterval: true, dmgInteval, intervalCount);
		firstHit = false;
	}

	public void EmitDebris()
	{
		if (floorCrack != null)
		{
			floorCrack.Fade(1f);
		}
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(6, transform.position + Vector3.up * 2f);
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(3, transform.position + Vector3.up * 2f, RockMedDebrisEmitter.SmallCircleExplosionOverride);
	}
}
