					currentSC.SetAttackStatus(givenStatus: true);
				}
				SoundManager.PlayAudioWithDistance("EarthCrumble", parent.transform.position, null, 24f, -1f, 1.1f);
			}
			else if (!dashCompleted)
			{
				parent.anim.PlayDirectional(parent.SlideAnimStr, -1, 0.25f);
			}
			else if (!explodeStarted)
			{
				explodeStarted = true;
				explodeStopwatch.SetDelay((!targetHit) ? 0.1f : 0.15f, stopCurrent: false, autoStart: true);
				if (currentSC != null)
				{
					currentSC.SetAttackStatus(givenStatus: false);
				}
			}
			else if (!explodeStopwatch.IsRunning)
			{
				ResetShield();
				PlayExplodeAnim(0.25f);
				parent.health.CurrentShieldValue = shieldOriginalValue;
				shieldOriValSet = true;
				base.ExecuteSkill();
			}
		}

		public override void FixedUpdate()
		{
			if (dashStarted && !dashCompleted && !dashStopwatch.IsRunning)
			{
				dashCompleted = true;
				parent.movement.EndMovement();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleEnemyFloorCollisions();
			ResetShield(explodeStatus: false);
			if (!shieldOriValSet && !fsm.nextStateName.Contains("Hurt") && !fsm.nextStateName.Contains("Dead"))
			{
				parent.health.CurrentShieldValue = shieldOriginalValue;
			}
		}

		private void PlayExplodeAnim(float givenTime)
		{
			if (parent.facingDirection == FacingDirection.Up || parent.facingDirection == FacingDirection.Down)
			{
				parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, givenTime);
			}
			else
			{
				parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, givenTime);
			}
		}

		private void CreateShield()
		{
			currentSC = ChaosInst<ShieldCharge>(ShieldCharge.Prefab, (Vector2)parent.attackOriginTrans.position + inputVector);
			currentSC.followTrans = parent.attackOriginTrans;
			currentSC.atkVector = inputVector;
			currentSC.SetAttackVars(parent.skillCategory, skillID);
			currentSC.attack.knockbackOverwriteVector = inputVector;
			Attack attack = currentSC.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = currentSC.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}

		private void ResetShield(bool explodeStatus = true)
		{
			if (!(currentSC == null))
			{
				Attack attack = currentSC.attack;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
				if (explodeStatus)
				{
					currentSC.ExplodeShield(explodeAtkLevel);
				}
				else
				{
					currentSC.Reset();
				}
				currentSC = null;
			}
		}

		private void OnTargetHit(Entity givenEnt)
		{
			if (!targetHit && !(givenEnt == null) && !(givenEnt is Destructible))
			{
				targetHit = true;
				parent.movement.EndMovement();
				parent.movement.MoveToMoveVector(1f);
			}
		}
	}

using UnityEngine;

public class ShieldCharge : MonoBehaviour
{
	private static GameObject prefab;

	public Sprite[] spriteVars;

	private SpriteRenderer spriteRenderer;

	public Attack attack;

	private CircleCollider2D attackCol;

	private string skillCat;

	private string skillID;

	public Vector2 atkVector;

	public Transform followTrans;

	private Vector3 followOffset;

	private Vector2 currentPosition;

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(5f);

	private bool resetQueued;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/ShieldCharge.prefab"));

	private void Awake()
	{
		spriteRenderer = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		attack = transform.Find("Attack").GetComponent<Attack>();
		attackCol = attack.GetComponent<CircleCollider2D>();
	}

	private void Start()
	{
		lifeStopwatch.IsRunning = true;
		attack.transform.localEulerAngles = Globals.GetRotationVector(-atkVector);
		attack.transform.localPosition = -atkVector * 1.5f;
		followOffset = atkVector;
		if (atkVector.x < 0f)
		{
			spriteRenderer.transform.localScale = new Vector3(-1f, 1f, 1f);
		}
		switch (Mathf.Clamp((int)((195f - Vector2.Angle(Vector2.up, atkVector)) * 0.033f), 0, 6))
		{
		case 0:
			spriteRenderer.sprite = spriteVars[0];
			break;
		case 1:
			spriteRenderer.sprite = spriteVars[1];
			break;
		case 2:
			spriteRenderer.sprite = spriteVars[1];
			break;
		case 3:
			spriteRenderer.sprite = spriteVars[2];
			break;
		case 4:
			spriteRenderer.sprite = spriteVars[3];
			break;
		case 5:
			spriteRenderer.sprite = spriteVars[3];
			break;
		case 6:
			spriteRenderer.sprite = spriteVars[4];
			break;
		}
		currentPosition = transform.position;
		CreateBurst(currentPosition, 1, 1.5f);
		SoundManager.PlayAudioWithDistance("BoulderShield", currentPosition);
		PoolManager.GetPoolItem<ParticleEffect>("RockFormEffect").Emit(10, currentPosition, RockFormEffect.SmallSettings);
	}

	private void LateUpdate()
	{
		if (!resetQueued)
		{
			if (!lifeStopwatch.IsRunning)
			{
				Reset();
			}
			if (followTrans != null)
			{
				transform.position = followTrans.position + followOffset;
			}
		}
	}

	public void SetAttackVars(string givenCat, string givenID)
	{
		skillCat = givenCat;
		skillID = givenID;
		attack.SetAttackInfo(skillCat, skillID, 2);
	}

	public void SetAttackStatus(bool givenStatus)
	{
		attackCol.enabled = givenStatus;
	}

	public void ExplodeShield(int givenAtkLevel)
	{
		if (!resetQueued)
		{
			attackCol.enabled = false;
			currentPosition = transform.position;
			CreateBurst(currentPosition, givenAtkLevel, 2f);
			SoundManager.PlayAudioWithDistance("EarthExplosionShort", currentPosition, null, 24f, -1f, 0.9f);
			SoundManager.PlayAudioWithDistance("EarthPebble", currentPosition);
			CameraController.ShakeCamera(0.25f);
			Reset(disableAttack: false);
		}
	}

	public void Reset(bool disableAttack = true)
	{
		if (!resetQueued)
		{
			resetQueued = true;
			currentPosition = transform.position;
			RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
			RockDebrisType debrisType = RockDebrisType.Default;
			int? particleCount = 4;
			Vector3? position = currentPosition;
			Vector3? localEulerAngles = Globals.GetRotationVector(atkVector);
			poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(RockDebrisType.Default, 6, currentPosition, RockDebrisEmitter.SmallCircleFastExplosionOverride);
			spriteRenderer.gameObject.SetActive(value: false);
			if (disableAttack)
			{
				attack.gameObject.SetActive(value: false);
			}
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 0.125f);
			}
		}
	}

	private void CreateBurst(Vector2 givenPosition, int givenLevel, float givenScale)
	{
		EarthBurst.CreateBurst(currentPosition, skillCat, skillID, givenLevel, givenScale).attack.knockbackOverwriteVector = atkVector;
	}
}

	public class UseThrowBoulder : ProjectileAttackState
	{
		public new static string staticID = "UseThrowBoulder";

		private ChaosQuickStopwatch riseStopwatch = new ChaosQuickStopwatch(0.125f);

		private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(1f / 32f);

		private Boulder currentTB;

		private Vector2 spawnPosition;

		private Vector2 throwPosition;

		private bool boulderThrown;

		private bool boulderSummoned;

		public UseThrowBoulder(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			SetAnimTimes();
		}

		public override void OnEnter()
		{
			BaseOnEnter();
			base.ExecuteSkill();
			inputVector = GetInputVector();
			parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animStartTime);
			spawnPosition = Globals.GetFailSafeLinecastVector(parent.transform.position, -Entity.GetFacingDirectionVector(parent.facingDirection), 1f, ChaosCollisions.layerUpperWallAndObst);
			throwPosition = spawnPosition + Vector2.up;
			SummonBoulder(spawnPosition);
			boulderSummoned = false;
			boulderThrown = false;
			riseStopwatch.IsRunning = true;
		}

		public override void Update()
		{
			if (!boulderThrown && currentTB != null)
			{
				currentTB.RefreshFlightTime();
			}
			if (riseStopwatch.IsRunning)
			{
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animStartTime);
			}
			else if (!boulderSummoned)
			{
				boulderSummoned = true;
				delayStopwatch.IsRunning = true;
			}
			else if (!boulderThrown)
			{
				if (!delayStopwatch.IsRunning)
				{
					parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
					boulderThrown = true;
					ThrowBoulder();
				}
			}
			else
			{
				ExitToSkillOrRunOrIdle();
			}
		}

		public override void FixedUpdate()
		{
			if (!boulderSummoned && !(currentTB == null))
			{
				currentTB.rigidbody2D.MovePosition(Vector2.Lerp(spawnPosition, throwPosition, riseStopwatch.TimePercentage));
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			if (!boulderThrown && currentTB != null)
			{
				currentTB.ResetProjectile();
				currentTB = null;
			}
		}

		private void SummonBoulder(Vector2 givenPosition)
		{
			SetSkillLevel(1);
			currentTB = (Boulder)CreateProjectile(Boulder.Prefab, givenPosition);
			currentTB.attackBox.damageOverride = -1;
			currentTB.projectileCollisionModifier = 1f;
			currentTB.UpdateCalculatedDamage();
			currentTB.goThroughWalls = true;
			currentTB.disableOnHit = false;
			currentTB.attackBox.knockbackOverwriteVector = -Entity.GetFacingDirectionVector(parent.facingDirection);
			PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, givenPosition);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(10, givenPosition);
			parent.dustEmitter.EmitCircle(40, 0.125f, -1f, -1f, givenPosition);
			SoundManager.PlayWithDistAndSPR("SummonRock", givenPosition);
			CameraController.ShakeCamera();
		}

		public void ThrowBoulder()
		{
			if (!(currentTB == null))
			{
				SetSkillLevel(2);
				currentTB.rigidbody2D.MovePosition(parent.attackOriginTrans.position);
				currentTB.attackBox.damageOverride = -1;
				FireProjectile(currentTB, inputVector, setKnockbackVector: true, 36f, 0.5f, "ThrowBoulder", setAtkInfo: true);
				currentTB.rotation = true;
				currentTB.goThroughWalls = false;
				currentTB.disableOnHit = true;
				currentTB.SetEmpowered(IsEmpowered);
				PoolManager.GetPoolItem<DashAirBurst>().Burst(currentTB.transform.position + (Vector3)inputVector * 2f, inputVector, useOffset: false);
				RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
				RockDebrisType debrisType = RockDebrisType.Default;
				int? particleCount = 3;
				Vector3? position = parent.attackOriginTrans.position;
				Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
				poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			}
		}
	}

	public class ProjectileAttackState : SkillState
	{
		private Projectile newProjectile;

		public ProjectileAttackState(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			isProjectileSkill = true;
		}

		public GameObject GetPrefabResource(string str)
		{
			return ChaosBundle.Get("Assets/Prefabs/Projectiles/" + str + ".prefab");
		}

		public virtual Projectile CreateProjectile(GameObject prefab, Vector3? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTrans = null, bool setAtkInfo = true)
		{
			newProjectile = Projectile.CreateProjectile(parent, prefab, (Vector2)((!givenPosition.HasValue) ? parent.attackOriginTrans.position : givenPosition.Value), (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value, parentTrans ?? parent.transform.parent);
			if (setAtkInfo)
			{
				SetProjectileAtkInfo(newProjectile);
			}
			return newProjectile;
		}

		public virtual void FireProjectile(Projectile projectile, Vector2 moveVector, bool setKnockbackVector = true, float newMoveSpeed = 0f, float newFlyTime = 0f, string audioString = "", bool setAtkInfo = false)
		{
			projectile.transform.SetParent(null);
			if (setAtkInfo)
			{
				SetProjectileAtkInfo(projectile);
			}
			projectile.moveVector = moveVector;
			if (setKnockbackVector)
			{
				projectile.attackBox.knockbackOverwriteVector = moveVector;
			}
			if (newMoveSpeed != 0f)
			{
				projectile.moveSpeed = newMoveSpeed;
			}
			if (newFlyTime != 0f)
			{
				projectile.flyTime = newFlyTime;
				projectile.lifeTime = newFlyTime * 2f;
			}
			projectile.RefreshFlightTime();
			if (audioString != string.Empty)
			{
				SoundManager.PlayWithDistAndSPR(audioString, projectile.transform.position);
			}
		}

		public virtual void SetProjectileAtkInfo(Projectile projectile)
		{
			projectile.attackBox.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
			projectile.UpdateCalculatedDamage(initDamageOverride: true);
		}
	}

