public class ThrownBoulder : ThrownItem
{
	private static GameObject prefab;

	[HideInInspector]
	public float riseHeight = 1f;

	[HideInInspector]
	public float riseTime = 1f;

	private int riseStopwatchID;

	public bool riseComplete;

	private Vector3 riseStartPosition;

	private Vector3 riseEndPosition;

	[HideInInspector]
	public Attack attackBox;

	private ParticleSystem debrisEmitter;

	private ChaosQuickStopwatch attackStopwatch;

	private float attackActiveTime = 0.1f;

	private Vector2 landPosition;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/ThrownItems/ThrownBoulder.prefab"));

	public float RisePercentage => ChaosStopwatch.GetTimePercentage(riseStopwatchID);

	public override void Awake()
	{
		base.Awake();
		attackBox = transform.Find("AttackBox").GetComponent<Attack>();
		spriteTrans = transform.Find("ItemSprite");
		landedHeight = spriteTrans.localPosition.y;
		debrisEmitter = spriteTrans.Find("DebrisEmitter").GetComponent<ParticleSystem>();
		attackStopwatch = new ChaosQuickStopwatch(attackActiveTime);
		riseComplete = false;
	}

	public override void Start()
	{
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position);
		riseStartPosition = spriteTrans.localPosition;
		riseEndPosition = riseStartPosition + Vector3.up * riseHeight;
		riseStopwatchID = ChaosStopwatch.Begin(riseTime);
	}

	public override void Update()
	{
		if (spriteRenderer != null)
		{
			spriteRenderer.sortingLayerName = ((!(spriteTrans.localPosition.y > 2f)) ? "Actor" : "OverlayDoodad");
		}
		if (!riseComplete)
		{
			spriteTrans.localPosition = Vector3.Lerp(riseStartPosition, riseEndPosition, ChaosStopwatch.GetTimePercentage(riseStopwatchID));
			if (!ChaosStopwatch.Check(riseStopwatchID))
			{
				return;
			}
			riseComplete = true;
			InitThrow();
		}
		if (throwComplete && !attackStopwatch.IsRunning)
		{
			attackBox.collider.enabled = false;
		}
	}

	public override void OnLanding()
	{
		base.OnLanding();
		attackBox.collider.enabled = true;
		attackStopwatch.IsRunning = true;
		spriteRenderer.enabled = false;
		debrisEmitter.Stop();
		landPosition = transform.position;
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(10, landPosition, RockMedDebrisEmitter.FloorExplosionOverrideR1);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 100;
		float scale = 1.5f;
		Vector3? emitPosition = landPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		PoolManager.GetPoolItem<FloorCrackEffect>().Crack(landPosition, 0f);
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, landPosition);
		string audioID = "EarthExplosion";
		Vector2? soundOrigin = landPosition;
		scale = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
		CameraController.ShakeCamera();
	}

	public void Break()
	{
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
	}
}

